    #[test]
    fn select_uextend_i32_to_i64() {
        // Zero-extend i32 to i64 by writing a W-register alias, which clears
        // the high 32 bits of the architectural X register.
        let sig = Signature {
            params: vec![Type::I32],
            returns: vec![Type::I64],
        };
        let mut isel = InstructionSelector::new_darwin_test("uxtw".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Uextend {
                    from_ty: Type::I32,
                    to_ty: Type::I64,
                },
                args: vec![Value(0)],
                results: vec![Value(1)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let inst = &mfunc.blocks[&entry].insts[1];
        assert_eq!(inst.opcode, AArch64Opcode::Uxtw);
        assert!(
            matches!(inst.operands[0], ISelOperand::VReg(v) if v.class == RegClass::Gpr64),
            "i32-to-i64 zero extension must define a Gpr64 destination"
        );
    }

