    #[test]
    fn select_narrow_pack_lanes_uses_neon_dup_and_ins_on_aarch64() {
        for (opcode, lane_count, lane_ty, element_size) in [
            (Opcode::V16I8PackLanes, 16, Type::I8, 1),
            (Opcode::V8I16PackLanes, 8, Type::I16, 2),
        ] {
            let (mut isel, entry) = make_empty_isel();
            for lane in 0..lane_count {
                let vreg = isel.new_vreg(RegClass::Gpr32);
                isel.define_value(Value(lane as u32), ISelOperand::VReg(vreg), lane_ty.clone());
            }

            isel.select_instruction(
                &Instruction {
                    opcode,
                    args: (0..lane_count).map(|lane| Value(lane as u32)).collect(),
                    results: vec![Value(100)],
                },
                entry,
            )
            .unwrap();

            let mfunc = isel.finalize();
            let insts = &mfunc.blocks[&entry].insts;
            assert_eq!(insts.len(), lane_count);
            assert_eq!(insts[0].opcode, AArch64Opcode::NeonDupGen);
            assert_eq!(insts[0].operands[2], ISelOperand::Imm(element_size));
            let dst = insts[0].operands[0].clone();
            assert!(matches!(dst, ISelOperand::VReg(vreg) if vreg.class == RegClass::Fpr128));
            for (lane, inst) in insts.iter().enumerate().take(lane_count).skip(1) {
                assert_eq!(inst.opcode, AArch64Opcode::NeonInsGen);
                assert_eq!(inst.operands[0], dst);
                assert_eq!(inst.operands[2], ISelOperand::Imm(lane as i64));
                assert_eq!(inst.operands[3], ISelOperand::Imm(element_size));
            }
        }
    }

    #[test]
    fn select_typed_vector_icmp_uses_neon_compare_on_aarch64() {
        for (opcode, expected_opcodes, arrangement, swaps_operands) in [
            (
                Opcode::V16I8Icmp { cond: IntCC::Equal },
                vec![AArch64Opcode::NeonCmeqV],
                1,
                false,
            ),
            (
                Opcode::V8I16Icmp {
                    cond: IntCC::NotEqual,
                },
                vec![AArch64Opcode::NeonCmeqV, AArch64Opcode::NeonNotV],
                3,
                false,
            ),
            (
                Opcode::V16I8Icmp {
                    cond: IntCC::UnsignedGreaterThan,
                },
                vec![AArch64Opcode::NeonCmhiV],
                1,
                false,
            ),
            (
                Opcode::V8I16Icmp {
                    cond: IntCC::UnsignedLessThanOrEqual,
                },
                vec![AArch64Opcode::NeonCmhsV],
                3,
                true,
            ),
            (
                Opcode::V4I32Icmp {
                    cond: IntCC::SignedGreaterThan,
                },
                vec![AArch64Opcode::NeonCmgtV],
                5,
                false,
            ),
            (
                Opcode::V4I32Icmp {
                    cond: IntCC::SignedLessThanOrEqual,
                },
                vec![AArch64Opcode::NeonCmgeV],
                5,
                true,
            ),
            (
                Opcode::V4I32Icmp {
                    cond: IntCC::UnsignedGreaterThan,
                },
                vec![AArch64Opcode::NeonCmhiV],
                5,
                false,
            ),
            (
                Opcode::V4I32Icmp {
                    cond: IntCC::UnsignedLessThan,
                },
                vec![AArch64Opcode::NeonCmhiV],
                5,
                true,
            ),
            (
                Opcode::V4I32Icmp {
                    cond: IntCC::UnsignedGreaterThanOrEqual,
                },
                vec![AArch64Opcode::NeonCmhsV],
                5,
                false,
            ),
            (
                Opcode::V4I32Icmp {
                    cond: IntCC::UnsignedLessThanOrEqual,
                },
                vec![AArch64Opcode::NeonCmhsV],
                5,
                true,
            ),
            (
                Opcode::V2I64Icmp {
                    cond: IntCC::SignedGreaterThan,
                },
                vec![AArch64Opcode::NeonCmgtV],
                6,
                false,
            ),
            (
                Opcode::V2I64Icmp {
                    cond: IntCC::SignedLessThan,
                },
                vec![AArch64Opcode::NeonCmgtV],
                6,
                true,
            ),
            (
                Opcode::V16I8Icmp {
                    cond: IntCC::SignedGreaterThanOrEqual,
                },
                vec![AArch64Opcode::NeonCmgeV],
                1,
                false,
            ),
            (
                Opcode::V8I16Icmp {
                    cond: IntCC::SignedLessThanOrEqual,
                },
                vec![AArch64Opcode::NeonCmgeV],
                3,
                true,
            ),
        ] {
            let (mut isel, entry) = make_empty_isel();
            let lhs = isel.new_vreg(RegClass::Fpr128);
            let rhs = isel.new_vreg(RegClass::Fpr128);
            let lhs_op = ISelOperand::VReg(lhs);
            let rhs_op = ISelOperand::VReg(rhs);
            isel.define_value(Value(0), ISelOperand::VReg(lhs), Type::V128);
            isel.define_value(Value(1), ISelOperand::VReg(rhs), Type::V128);

            isel.select_instruction(
                &Instruction {
                    opcode,
                    args: vec![Value(0), Value(1)],
                    results: vec![Value(2)],
                },
                entry,
            )
            .unwrap();

            let insts = &isel.func.blocks[&entry].insts;
            assert_eq!(
                insts.iter().map(|inst| inst.opcode).collect::<Vec<_>>(),
                expected_opcodes,
                "unexpected typed vector ICmp AArch64 lowering: {insts:?}"
            );
            let (expected_lhs, expected_rhs) = if swaps_operands {
                (rhs_op, lhs_op)
            } else {
                (lhs_op, rhs_op)
            };
            assert_eq!(insts[0].operands[1], expected_lhs);
            assert_eq!(insts[0].operands[2], expected_rhs);
            assert_eq!(
                insts[0].operands.last(),
                Some(&ISelOperand::Imm(arrangement))
            );
            if insts.len() == 2 {
                assert_eq!(insts[1].opcode, AArch64Opcode::NeonNotV);
                assert_eq!(insts[1].operands[1], insts[0].operands[0]);
            }
        }
    }

    #[test]
