    #[test]
    fn select_vector_insert_lanes_use_copy_and_neon_ins_on_aarch64() {
        for (opcode, lane, element_size, lane_class, lane_ty) in [
            (
                Opcode::V4I32InsertLane { lane: 2 },
                2,
                4,
                RegClass::Gpr32,
                Type::I32,
            ),
            (
                Opcode::V16I8InsertLane { lane: 15 },
                15,
                1,
                RegClass::Gpr32,
                Type::I8,
            ),
            (
                Opcode::V8I16InsertLane { lane: 7 },
                7,
                2,
                RegClass::Gpr32,
                Type::I16,
            ),
            (
                Opcode::V2I64InsertLane { lane: 1 },
                1,
                8,
                RegClass::Gpr64,
                Type::I64,
            ),
        ] {
            let (mut isel, entry) = make_empty_isel();
            let vector = isel.new_vreg(RegClass::Fpr128);
            let lane_vreg = isel.new_vreg(lane_class);
            isel.define_value(Value(0), ISelOperand::VReg(vector), Type::V128);
            isel.define_value(Value(1), ISelOperand::VReg(lane_vreg), lane_ty);

            isel.select_instruction(
                &Instruction {
                    opcode,
                    args: vec![Value(0), Value(1)],
                    results: vec![Value(2)],
                },
                entry,
            )
            .unwrap();

            assert_eq!(isel.value_type(&Value(2)), Type::V128);
            let mfunc = isel.finalize();
            let insts = &mfunc.blocks[&entry].insts;
            assert_eq!(insts.len(), 2);
            assert_eq!(insts[0].opcode, AArch64Opcode::Copy);
            assert!(matches!(
                insts[0].operands[0],
                ISelOperand::VReg(vreg) if vreg.class == RegClass::Fpr128
            ));
            let dst = insts[0].operands[0].clone();
            assert_eq!(insts[1].opcode, AArch64Opcode::NeonInsGen);
            assert_eq!(insts[1].operands[0], dst);
            assert_eq!(insts[1].operands[2], ISelOperand::Imm(lane));
            assert_eq!(insts[1].operands[3], ISelOperand::Imm(element_size));
        }
    }

