    #[test]
    fn select_v4i32_mask_extract_uses_umov_and_scalar_pack_on_aarch64() {
        let (mut isel, entry) = make_empty_isel();
        let mask = isel.new_vreg(RegClass::Fpr128);
        isel.define_value(Value(0), ISelOperand::VReg(mask), Type::V128);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::V4I32MaskExtract,
                args: vec![Value(0)],
                results: vec![Value(1)],
            },
            entry,
        )
        .unwrap();

        assert_eq!(isel.value_type(&Value(1)), Type::I32);
        let insts = &isel.func.blocks[&entry].insts;
        assert_eq!(insts.len(), 18);
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == AArch64Opcode::NeonUmovGen)
                .count(),
            4
        );
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == AArch64Opcode::LsrRI)
                .count(),
            4
        );
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == AArch64Opcode::AndRI)
                .count(),
            4
        );
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == AArch64Opcode::LslRI)
                .count(),
            3
        );
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == AArch64Opcode::OrrRR)
                .count(),
            3
        );
        let umov_lanes: Vec<_> = insts
            .iter()
            .filter(|inst| inst.opcode == AArch64Opcode::NeonUmovGen)
            .map(|inst| (inst.operands[2].clone(), inst.operands[3].clone()))
            .collect();
        assert_eq!(
            umov_lanes,
            vec![
                (ISelOperand::Imm(0), ISelOperand::Imm(4)),
                (ISelOperand::Imm(1), ISelOperand::Imm(4)),
                (ISelOperand::Imm(2), ISelOperand::Imm(4)),
                (ISelOperand::Imm(3), ISelOperand::Imm(4)),
            ]
        );
    }

