    /// Regression: the i8 ctpop SWAR sequence used to mask its constants down to
    /// the operand width, emitting `AND Wd, Wn, #0x55` (and 0x33, 0x0f0f-style
    /// narrowed values) which are NOT valid AArch64 32-bit logical immediates,
    /// so the encoder aborted. Every `AndRI` immediate emitted for a narrow
    /// ctpop must be encodable as a 32-bit logical immediate.
    #[test]
    fn select_ctpop_i8_emits_only_encodable_logical_imms() {
        // Standalone AArch64 32-bit logical-immediate encodability check
        // (matches the codegen encoder's contract without depending on it).
        fn is_encodable_logical_imm32(value: u64) -> bool {
            const DATASIZE: u32 = 32;
            let value = value & 0xffff_ffff;
            if value == 0 || value == 0xffff_ffff {
                return false;
            }
            let mut esize = 2u32;
            while esize <= DATASIZE {
                if DATASIZE.is_multiple_of(esize) {
                    let elem = value & ((1u64 << esize) - 1);
                    let mut replicated = true;
                    let mut v = value;
                    for _ in 0..(DATASIZE / esize) {
                        if v & ((1u64 << esize) - 1) != elem {
                            replicated = false;
                            break;
                        }
                        v >>= esize;
                    }
                    if replicated {
                        // Within the element, some rotation must be a contiguous
                        // run of ones (`(1<<k)-1`, with 1 <= k < esize).
                        let mask = (1u64 << esize) - 1;
                        for r in 0..esize {
                            let rot = ((elem >> r) | (elem << (esize - r))) & mask;
                            if rot != 0 && rot != mask && (rot & (rot + 1)) == 0 {
                                return true;
                            }
                        }
                        return false;
                    }
                }
                esize <<= 1;
            }
            false
        }

        let (mut isel, entry) = make_empty_isel();
        let src = Value(0);
        let result = Value(1);
        // i8 ctpop lowers into Gpr32 (see reg_class_for_type).
        let src_vreg = isel.new_vreg(RegClass::Gpr32);
        isel.define_value(src, ISelOperand::VReg(src_vreg), Type::I8);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::CtPop,
                args: vec![src],
                results: vec![result],
            },
            entry,
        )
        .unwrap();

        assert_eq!(isel.value_types.get(&result), Some(&Type::I8));
        let mfunc = isel.finalize();
        let mut saw_and = false;
        for inst in &mfunc.blocks[&entry].insts {
            if inst.opcode == AArch64Opcode::AndRI {
                saw_and = true;
                let ISelOperand::Imm(imm) = inst.operands[2] else {
                    panic!(
                        "AndRI immediate operand must be an Imm, got {:?}",
                        inst.operands[2]
                    );
                };
                assert!(
                    is_encodable_logical_imm32(imm as u64),
                    "i8 ctpop emitted non-encodable AND immediate {:#x}",
                    imm as u64,
                );
            }
        }
        assert!(
            saw_and,
            "expected the i8 ctpop SWAR sequence to emit AndRI masks"
        );
    }

    #[test]
    fn select_ctpop_i128_sums_both_halves() {
        let (mut isel, entry) = make_empty_isel();
        // An i128 source needs BOTH halves bound (register pair).
        let src = Value(0);
        let lo = isel.new_vreg(RegClass::Gpr64);
        let hi = isel.new_vreg(RegClass::Gpr64);
        isel.define_i128_value(src, lo, hi);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::CtPop,
                args: vec![src],
                results: vec![Value(1)],
            },
            entry,
        )
        .expect("i128 ctpop should lower (popcount of each half, summed)");

        // The result is a bound i128 register pair (low = count, high = 0).
        assert_eq!(isel.value_type(&Value(1)), Type::I128);
        assert!(
            isel.i128_high_map.contains_key(&Value(1)),
            "i128 ctpop result must bind its high half"
        );

        // The two per-half SWARs are summed with an AddRR, and the high half is
        // materialized to zero with a MOVZ.
        let ops: Vec<_> = isel.func.blocks[&entry]
            .insts
            .iter()
            .map(|i| i.opcode)
            .collect();
        assert!(
            ops.contains(&AArch64Opcode::AddRR),
            "expected an AddRR summing the two half popcounts, got {ops:?}"
        );
        assert!(
            ops.contains(&AArch64Opcode::Movz),
            "expected a MOVZ zeroing the high half, got {ops:?}"
        );
    }

    #[test]
    fn select_vector_and_float_atomics_fail_closed() {
        // I128 atomics lower through the LDXP/STXP pair pseudos (see
        // i128_atomics_select_pair_llsc_pseudos_on_every_profile). The V128
        // vector and scalar float forms have no atomic lowering: emitting a
        // GPR atomic over an FPR value (or over the low half of a vector) would
        // be a wrong-register-file / wrong-atomic-semantics miscompile, so each
        // op must fail CLOSED. (The guards return before any operand is read,
        // so undefined placeholder operands are fine.)
        for ty in [Type::V128, Type::F32] {
            {
                let (mut isel, entry) = make_empty_isel();
                let err = isel
                    .select_instruction(
                        &Instruction {
                            opcode: Opcode::AtomicLoad {
                                ty: ty.clone(),
                                ordering: AtomicOrdering::SeqCst,
                            },
                            args: vec![Value(0)],
                            results: vec![Value(1)],
                        },
                        entry,
                    )
                    .unwrap_err();
                assert!(
                    matches!(err, ISelError::UnsupportedOpcode(_)),
                    "{ty:?} AtomicLoad must fail closed, got {err:?}"
                );
            }
            {
                let (mut isel, entry) = make_empty_isel();
                let err = isel
                    .select_instruction(
                        &Instruction {
                            opcode: Opcode::AtomicStore {
                                ty: ty.clone(),
                                ordering: AtomicOrdering::SeqCst,
                            },
                            args: vec![Value(0), Value(1)],
                            results: vec![],
                        },
                        entry,
                    )
                    .unwrap_err();
                assert!(
                    matches!(err, ISelError::UnsupportedOpcode(_)),
                    "{ty:?} AtomicStore must fail closed, got {err:?}"
                );
            }
            {
                let (mut isel, entry) = make_empty_isel();
                let err = isel
                    .select_instruction(
                        &Instruction {
                            opcode: Opcode::CmpXchg {
                                ty: ty.clone(),
                                success: AtomicOrdering::SeqCst,
                                failure: AtomicOrdering::SeqCst,
                            },
                            args: vec![Value(0), Value(1), Value(2)],
                            results: vec![Value(3)],
                        },
                        entry,
                    )
                    .unwrap_err();
                assert!(
                    matches!(err, ISelError::UnsupportedCmpXchg { .. }),
                    "{ty:?} CmpXchg must fail closed, got {err:?}"
                );
            }
        }
    }

    fn fresh_value(next: &mut u32) -> Value {
        let value = Value(*next);
        *next += 1;
        value
    }

    fn push_bitreverse_iconst(
        instrs: &mut Vec<Instruction>,
        next: &mut u32,
        ty: &Type,
        imm: i64,
    ) -> Value {
        let value = fresh_value(next);
        instrs.push(Instruction {
            opcode: Opcode::Iconst {
                ty: ty.clone(),
                imm,
            },
            args: vec![],
            results: vec![value],
        });
        value
    }

    fn bitreverse_ladder(ty: Type, src: Value, dst: Value) -> (Vec<Instruction>, Value) {
        let (steps, final_shift) = InstructionSelector::bitreverse_spec(&ty).unwrap();
        let mut instrs = Vec::new();
        let mut next = 100;
        let mut current = src;
        let mut first_combined = None;

        for &(shift, mask) in steps {
            let shift_val = push_bitreverse_iconst(&mut instrs, &mut next, &ty, i64::from(shift));
            let mask_val = push_bitreverse_iconst(&mut instrs, &mut next, &ty, mask);
            let right = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Ushr,
                args: vec![current, shift_val],
                results: vec![right],
            });
            let right_masked = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Band,
                args: vec![right, mask_val],
                results: vec![right_masked],
            });
            let left_masked = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Band,
                args: vec![current, mask_val],
                results: vec![left_masked],
            });
            let left = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Ishl,
                args: vec![left_masked, shift_val],
                results: vec![left],
            });
            let combined = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Bor,
                args: vec![right_masked, left],
                results: vec![combined],
            });
            first_combined.get_or_insert(combined);
            current = combined;
        }

        let final_shift_val =
            push_bitreverse_iconst(&mut instrs, &mut next, &ty, i64::from(final_shift));
        let right = fresh_value(&mut next);
        instrs.push(Instruction {
            opcode: Opcode::Ushr,
            args: vec![current, final_shift_val],
            results: vec![right],
        });
        let left = fresh_value(&mut next);
        instrs.push(Instruction {
            opcode: Opcode::Ishl,
            args: vec![current, final_shift_val],
            results: vec![left],
        });
        instrs.push(Instruction {
            opcode: Opcode::Bor,
            args: vec![right, left],
            results: vec![dst],
        });

        (instrs, first_combined.unwrap())
    }

    fn bitreverse_signed_imm(ty: &Type, bits: u64) -> i64 {
        match ty {
            Type::I32 => (bits as u32 as i32) as i64,
            Type::I64 => bits as i64,
            other => panic!("unsupported bitreverse test type: {other:?}"),
        }
    }

    fn push_bitreverse_stack_load(
        instrs: &mut Vec<Instruction>,
        next: &mut u32,
        ty: &Type,
        ptr: Value,
    ) -> Value {
        let load = fresh_value(next);
        instrs.push(Instruction {
            opcode: Opcode::Load {
                ty: ty.clone(),
                align: None,
            },
            args: vec![ptr],
            results: vec![load],
        });
        load
    }

    fn bitreverse_stack_byte_swap_ladder(ty: Type, src: Value, dst: Value) -> Vec<Instruction> {
        let (steps, _) = InstructionSelector::bitreverse_spec(&ty).unwrap();
        let mut instrs = Vec::new();
        let mut next = 100;
        let ptr = fresh_value(&mut next);
        instrs.push(Instruction {
            opcode: Opcode::StackAddr { slot: 0 },
            args: vec![],
            results: vec![ptr],
        });
        instrs.push(Instruction {
            opcode: Opcode::Store {
                ty: ty.clone(),
                align: None,
            },
            args: vec![src, ptr],
            results: vec![],
        });

        for &(shift, mask) in &steps[..3] {
            let shift_val = push_bitreverse_iconst(&mut instrs, &mut next, &ty, i64::from(shift));
            let mask_val = push_bitreverse_iconst(&mut instrs, &mut next, &ty, mask);
            let right_load = push_bitreverse_stack_load(&mut instrs, &mut next, &ty, ptr);
            let right = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Ushr,
                args: vec![right_load, shift_val],
                results: vec![right],
            });
            let right_masked = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Band,
                args: vec![right, mask_val],
                results: vec![right_masked],
            });
            let left_load = push_bitreverse_stack_load(&mut instrs, &mut next, &ty, ptr);
            let left_masked = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Band,
                args: vec![left_load, mask_val],
                results: vec![left_masked],
            });
            let left = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Ishl,
                args: vec![left_masked, shift_val],
                results: vec![left],
            });
            let combined = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Bor,
                args: vec![right_masked, left],
                results: vec![combined],
            });
            instrs.push(Instruction {
                opcode: Opcode::Store {
                    ty: ty.clone(),
                    align: None,
                },
                args: vec![combined, ptr],
                results: vec![],
            });
        }

        let mut byte_terms = Vec::new();
        let terms = InstructionSelector::bitreverse_byte_swap_terms(&ty).unwrap();
        for (mask_bits, shift_left, shift) in terms.into_iter().rev() {
            let load = push_bitreverse_stack_load(&mut instrs, &mut next, &ty, ptr);
            let mask_val = push_bitreverse_iconst(
                &mut instrs,
                &mut next,
                &ty,
                bitreverse_signed_imm(&ty, mask_bits),
            );
            let masked = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Band,
                args: vec![load, mask_val],
                results: vec![masked],
            });
            let shift_val = push_bitreverse_iconst(&mut instrs, &mut next, &ty, i64::from(shift));
            let shifted = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: if shift_left {
                    Opcode::Ishl
                } else {
                    Opcode::Ushr
                },
                args: vec![masked, shift_val],
                results: vec![shifted],
            });
            byte_terms.push(shifted);
        }

        let mut acc = byte_terms[0];
        for (idx, term) in byte_terms.iter().copied().enumerate().skip(1) {
            let result = if idx == byte_terms.len() - 1 {
                dst
            } else {
                fresh_value(&mut next)
            };
            instrs.push(Instruction {
                opcode: Opcode::Bor,
                args: vec![acc, term],
                results: vec![result],
            });
            acc = result;
        }

        instrs
    }

    #[test]
    fn select_bitreverse_i32_ladder_emits_rbit() {
        let sig = Signature {
            params: vec![Type::I32],
            returns: vec![Type::I32],
        };
        let mut isel = InstructionSelector::new_darwin_test("bitrev32".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        let (instrs, _) = bitreverse_ladder(Type::I32, Value(0), Value(1));
        isel.select_block(entry, &instrs).unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        let rbits: Vec<_> = insts
            .iter()
            .filter(|inst| inst.opcode == AArch64Opcode::Rbit)
            .collect();
        assert_eq!(rbits.len(), 1, "expected one RBIT, got {insts:?}");
        assert!(
            !insts.iter().any(|inst| matches!(
                inst.opcode,
                AArch64Opcode::LsrRI
                    | AArch64Opcode::LslRI
                    | AArch64Opcode::AndRI
                    | AArch64Opcode::OrrRR
            )),
            "bitreverse ladder should be skipped after RBIT selection: {insts:?}"
        );
        match rbits[0].operands[0] {
            ISelOperand::VReg(vreg) => assert_eq!(vreg.class, RegClass::Gpr32),
            ref other => panic!("expected Gpr32 RBIT destination, got {other:?}"),
        }
    }

    #[test]
    fn select_bitreverse_i64_ladder_emits_rbit() {
        let sig = Signature {
            params: vec![Type::I64],
            returns: vec![Type::I64],
        };
        let mut isel = InstructionSelector::new_darwin_test("bitrev64".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        let (instrs, _) = bitreverse_ladder(Type::I64, Value(0), Value(1));
        isel.select_block(entry, &instrs).unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        let rbit = insts
            .iter()
            .find(|inst| inst.opcode == AArch64Opcode::Rbit)
            .expect("expected RBIT for i64 bitreverse ladder");
        match rbit.operands[0] {
            ISelOperand::VReg(vreg) => assert_eq!(vreg.class, RegClass::Gpr64),
            ref other => panic!("expected Gpr64 RBIT destination, got {other:?}"),
        }
    }

    /// Select `blocks` as one function the way the production driver does:
    /// the adapter's slot metadata is set and the whole-function use counts
    /// and stack-slot address facts are seeded before any block is selected.
    fn select_seeded_function(
        name: &str,
        ty: &Type,
        blocks: Vec<(Block, Vec<Instruction>)>,
        slots: Vec<StackSlotInfo>,
    ) -> ISelFunction {
        let sig = Signature {
            params: vec![ty.clone()],
            returns: vec![ty.clone()],
        };
        select_seeded_function_with_sig(name, sig, blocks, slots)
    }

    fn select_seeded_function_with_sig(
        name: &str,
        sig: Signature,
        blocks: Vec<(Block, Vec<Instruction>)>,
        slots: Vec<StackSlotInfo>,
    ) -> ISelFunction {
        let mut function = crate::function::Function::new(name, sig.clone());
        for (block, instructions) in &blocks {
            function.block_order.push(*block);
            function.blocks.insert(
                *block,
                crate::function::BasicBlock {
                    params: vec![],
                    instructions: instructions.clone(),
                    source_locs: vec![],
                },
            );
        }
        let mut isel = InstructionSelector::new_darwin_test(name.to_string(), sig.clone());
        isel.set_stack_slots(slots);
        isel.seed_function_value_use_counts(&function);
        isel.lower_formal_arguments(&sig, blocks[0].0).unwrap();
        for (block, instructions) in &blocks {
            isel.select_block(*block, instructions).unwrap();
        }
        isel.finalize()
    }

    /// The adapter's slot for a scalar local of `ty`.
    fn bitreverse_scalar_slot(ty: &Type) -> StackSlotInfo {
        StackSlotInfo::new(ty.bytes(), ty.bytes())
    }

    fn bitreverse_return(value: Value) -> Instruction {
        Instruction {
            opcode: Opcode::Return,
            args: vec![value],
            results: vec![],
        }
    }

    /// The stack-slot ladder of `ty` reversing `Value(0)` into `Value(1)`,
    /// with `tail` appended after its root. Returns the instructions, the
    /// root's index and the indices of the ladder's slot stores.
    fn bitreverse_stack_ladder_with_tail(
        ty: &Type,
        tail: Vec<Instruction>,
    ) -> (Vec<Instruction>, usize, Vec<usize>) {
        let mut instrs = bitreverse_stack_byte_swap_ladder(ty.clone(), Value(0), Value(1));
        let root = instrs.len() - 1;
        assert_eq!(instrs[root].results, vec![Value(1)]);
        let stores = instrs
            .iter()
            .enumerate()
            .filter(|(_, inst)| matches!(inst.opcode, Opcode::Store { .. }))
            .map(|(idx, _)| idx)
            .collect();
        instrs.extend(tail);
        (instrs, root, stores)
    }

    fn count_opcode(func: &ISelFunction, block: Block, opcode: AArch64Opcode) -> usize {
        func.blocks[&block]
            .insts
            .iter()
            .filter(|inst| inst.opcode == opcode)
            .count()
    }

    #[test]
    fn select_bitreverse_stack_ladder_folds_private_slot_and_links_stores_to_rbit() {
        for (ty, class) in [(Type::I32, RegClass::Gpr32), (Type::I64, RegClass::Gpr64)] {
            let (instrs, root, stores) =
                bitreverse_stack_ladder_with_tail(&ty, vec![bitreverse_return(Value(1))]);
            assert_eq!(
                stores.len(),
                4,
                "{ty:?}: the initial store and three swap stores"
            );
            let entry = Block(0);
            let mfunc = select_seeded_function(
                "bitrev_stack",
                &ty,
                vec![(entry, instrs)],
                vec![bitreverse_scalar_slot(&ty)],
            );
            let block = &mfunc.blocks[&entry];
            let rbits: Vec<usize> = block
                .insts
                .iter()
                .enumerate()
                .filter(|(_, inst)| inst.opcode == AArch64Opcode::Rbit)
                .map(|(idx, _)| idx)
                .collect();
            assert_eq!(
                rbits.len(),
                1,
                "{ty:?}: expected one RBIT: {:?}",
                block.insts
            );
            match block.insts[rbits[0]].operands[0] {
                ISelOperand::VReg(vreg) => assert_eq!(vreg.class, class, "{ty:?}"),
                ref other => panic!("{ty:?}: expected a VReg RBIT destination, got {other:?}"),
            }
            assert!(
                !block.insts.iter().any(|inst| matches!(
                    inst.opcode,
                    AArch64Opcode::LdrRI
                        | AArch64Opcode::StrRI
                        | AArch64Opcode::LsrRI
                        | AArch64Opcode::LslRI
                        | AArch64Opcode::AndRI
                        | AArch64Opcode::OrrRR
                )),
                "{ty:?}: the private-slot ladder should be folded into RBIT: {:?}",
                block.insts
            );
            let root_id = SourceInstId {
                block: 0,
                index: root as u32,
            };
            assert_eq!(
                block.lowering_provenance[rbits[0]].source_id(),
                Some(root_id),
                "{ty:?}: the RBIT is stamped with the ladder's root"
            );
            let ir = mfunc.to_ir_func();
            for store in &stores {
                let source = SourceInstId {
                    block: 0,
                    index: *store as u32,
                };
                assert_eq!(mfunc.source_fusion_target(source), Some(root_id), "{ty:?}");
                assert_eq!(ir.source_fusion_target(source), Some(root_id), "{ty:?}");
            }
            assert_eq!(
                ir.source_fusion_targets.len(),
                stores.len(),
                "{ty:?}: only the folded stores carry fusion edges"
            );
            assert_eq!(
                mfunc.stack_slots,
                vec![StackSlotInfo::new(0, 1)],
                "{ty:?}: the folded slot keeps its id but no storage"
            );
        }
    }

    /// Every negative control keeps each ladder instruction, including all
    /// four slot stores, records no fusion edge and keeps the slot's storage.
    fn assert_stack_ladder_not_fused(func: &ISelFunction, ty: &Type, slots: usize, what: &str) {
        let entry = Block(0);
        assert_eq!(
            count_opcode(func, entry, AArch64Opcode::Rbit),
            0,
            "{what}: must not fold the ladder: {:?}",
            func.blocks[&entry].insts
        );
        assert!(
            count_opcode(func, entry, AArch64Opcode::StrRI) >= 4,
            "{what}: every slot store must be emitted: {:?}",
            func.blocks[&entry].insts
        );
        assert!(func.source_fusion_targets.is_empty(), "{what}");
        assert_eq!(func.stack_slots.len(), slots, "{what}");
        assert_eq!(func.stack_slots[0], bitreverse_scalar_slot(ty), "{what}");
    }

    /// A second address of the ladder's slot 0, outside the matched window.
    fn bitreverse_other_slot_addr() -> Instruction {
        Instruction {
            opcode: Opcode::StackAddr { slot: 0 },
            args: vec![],
            results: vec![Value(900)],
        }
    }

    #[test]
    fn select_bitreverse_stack_ladder_keeps_stores_when_the_slot_is_read_elsewhere() {
        let ty = Type::I32;
        let (instrs, _, _) = bitreverse_stack_ladder_with_tail(
            &ty,
            vec![
                bitreverse_other_slot_addr(),
                Instruction {
                    opcode: Opcode::Load {
                        ty: ty.clone(),
                        align: None,
                    },
                    args: vec![Value(900)],
                    results: vec![Value(901)],
                },
                Instruction {
                    opcode: Opcode::Bxor,
                    args: vec![Value(1), Value(901)],
                    results: vec![Value(902)],
                },
                bitreverse_return(Value(902)),
            ],
        );
        let func = select_seeded_function(
            "other_load",
            &ty,
            vec![(Block(0), instrs)],
            vec![bitreverse_scalar_slot(&ty)],
        );
        assert_stack_ladder_not_fused(&func, &ty, 1, "another load of the slot");
    }

    #[test]
    fn select_bitreverse_stack_ladder_keeps_stores_when_the_slot_is_written_elsewhere() {
        let ty = Type::I32;
        let (instrs, _, _) = bitreverse_stack_ladder_with_tail(
            &ty,
            vec![
                bitreverse_other_slot_addr(),
                Instruction {
                    opcode: Opcode::Store {
                        ty: ty.clone(),
                        align: None,
                    },
                    args: vec![Value(1), Value(900)],
                    results: vec![],
                },
                bitreverse_return(Value(1)),
            ],
        );
        let func = select_seeded_function(
            "other_store",
            &ty,
            vec![(Block(0), instrs)],
            vec![bitreverse_scalar_slot(&ty)],
        );
        assert_stack_ladder_not_fused(&func, &ty, 1, "another store to the slot");
        assert_eq!(count_opcode(&func, Block(0), AArch64Opcode::StrRI), 5);
    }

    #[test]
    fn select_bitreverse_stack_ladder_keeps_stores_when_the_address_escapes() {
        let ty = Type::I32;
        // To a callee.
        let (instrs, _, _) = bitreverse_stack_ladder_with_tail(
            &ty,
            vec![
                bitreverse_other_slot_addr(),
                Instruction {
                    opcode: Opcode::Call {
                        name: "observe".to_string(),
                        binding: DirectCallBinding::Interposable,
                    },
                    args: vec![Value(900)],
                    results: vec![],
                },
                bitreverse_return(Value(1)),
            ],
        );
        let func = select_seeded_function(
            "escaped_to_call",
            &ty,
            vec![(Block(0), instrs)],
            vec![bitreverse_scalar_slot(&ty)],
        );
        assert_stack_ladder_not_fused(&func, &ty, 1, "an address passed to a call");
        assert_eq!(count_opcode(&func, Block(0), AArch64Opcode::Bl), 1);

        // Into memory, stored as data.
        let (instrs, _, _) = bitreverse_stack_ladder_with_tail(
            &ty,
            vec![
                bitreverse_other_slot_addr(),
                Instruction {
                    opcode: Opcode::StackAddr { slot: 1 },
                    args: vec![],
                    results: vec![Value(903)],
                },
                Instruction {
                    opcode: Opcode::Store {
                        ty: Type::I64,
                        align: None,
                    },
                    args: vec![Value(900), Value(903)],
                    results: vec![],
                },
                bitreverse_return(Value(1)),
            ],
        );
        let func = select_seeded_function(
            "escaped_to_memory",
            &ty,
            vec![(Block(0), instrs)],
            vec![bitreverse_scalar_slot(&ty), StackSlotInfo::new(8, 8)],
        );
        assert_stack_ladder_not_fused(&func, &ty, 2, "an address stored to memory");
    }

    #[test]
    fn select_bitreverse_stack_ladder_keeps_stores_when_another_block_reads_the_slot() {
        // Only the whole-function facts can see an access in another block.
        let ty = Type::I32;
        let (mut instrs, _, _) = bitreverse_stack_ladder_with_tail(&ty, vec![]);
        instrs.push(Instruction {
            opcode: Opcode::Jump { dest: Block(1) },
            args: vec![],
            results: vec![],
        });
        let other_block = vec![
            bitreverse_other_slot_addr(),
            Instruction {
                opcode: Opcode::Load {
                    ty: ty.clone(),
                    align: None,
                },
                args: vec![Value(900)],
                results: vec![Value(901)],
            },
            bitreverse_return(Value(901)),
        ];
        let func = select_seeded_function(
            "other_block_load",
            &ty,
            vec![(Block(0), instrs), (Block(1), other_block)],
            vec![bitreverse_scalar_slot(&ty)],
        );
        assert_stack_ladder_not_fused(&func, &ty, 1, "a load of the slot in another block");
    }

    #[test]
    fn select_bitreverse_stack_ladder_keeps_stores_on_width_mismatch() {
        let ty = Type::I32;

        // An i64 argument enters an 8-byte slot through an i64 store and the
        // 32-bit ladder reads its low half back: well defined, but the
        // initial store is not the ladder's width.
        let (mut instrs, _, stores) =
            bitreverse_stack_ladder_with_tail(&ty, vec![bitreverse_return(Value(1))]);
        instrs[stores[0]].opcode = Opcode::Store {
            ty: Type::I64,
            align: None,
        };
        let func = select_seeded_function_with_sig(
            "wide_store",
            Signature {
                params: vec![Type::I64],
                returns: vec![ty.clone()],
            },
            vec![(Block(0), instrs)],
            vec![StackSlotInfo::new(8, 8)],
        );
        let entry = Block(0);
        assert_eq!(count_opcode(&func, entry, AArch64Opcode::Rbit), 0);
        assert!(count_opcode(&func, entry, AArch64Opcode::StrRI) >= 4);
        assert!(func.source_fusion_targets.is_empty());
        assert_eq!(func.stack_slots, vec![StackSlotInfo::new(8, 8)]);

        // The slot is narrower than the ladder's 32-bit accesses.
        let (instrs, _, _) =
            bitreverse_stack_ladder_with_tail(&ty, vec![bitreverse_return(Value(1))]);
        let func = select_seeded_function(
            "narrow_slot",
            &ty,
            vec![(Block(0), instrs)],
            vec![StackSlotInfo::new(2, 2)],
        );
        assert_eq!(count_opcode(&func, entry, AArch64Opcode::Rbit), 0);
        assert!(count_opcode(&func, entry, AArch64Opcode::StrRI) >= 4);
        assert!(func.source_fusion_targets.is_empty());
        assert_eq!(func.stack_slots, vec![StackSlotInfo::new(2, 2)]);
    }

    #[test]
    fn select_bitreverse_stack_ladder_without_function_facts_keeps_stores() {
        // A block-at-a-time driver that never seeded whole-function facts
        // cannot prove any slot private, so the ladder stays unfused.
        let ty = Type::I32;
        let sig = Signature {
            params: vec![ty.clone()],
            returns: vec![ty.clone()],
        };
        let mut isel = InstructionSelector::new_darwin_test("unseeded".to_string(), sig.clone());
        isel.set_stack_slots(vec![bitreverse_scalar_slot(&ty)]);
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();
        let (instrs, _, _) =
            bitreverse_stack_ladder_with_tail(&ty, vec![bitreverse_return(Value(1))]);
        isel.select_block(entry, &instrs).unwrap();
        let func = isel.finalize();
        assert_stack_ladder_not_fused(&func, &ty, 1, "unseeded function facts");
    }

    #[test]
    fn select_bitreverse_stack_byte_swap_rejects_wrong_final_mask() {
        let ty = Type::I32;
        let (mut instrs, _, _) =
            bitreverse_stack_ladder_with_tail(&ty, vec![bitreverse_return(Value(1))]);
        let mask = instrs
            .iter_mut()
            .rev()
            .find_map(|inst| match &mut inst.opcode {
                Opcode::Iconst { ty: Type::I32, imm } if *imm == 0xff => Some(imm),
                _ => None,
            })
            .expect("expected low-byte final mask");
        *mask = 0xfe;

        let func = select_seeded_function(
            "bitrev32_bad_mask",
            &ty,
            vec![(Block(0), instrs)],
            vec![bitreverse_scalar_slot(&ty)],
        );
        assert_stack_ladder_not_fused(&func, &ty, 1, "an incorrect final mask");
        assert!(
            count_opcode(&func, Block(0), AArch64Opcode::LdrRI) > 0,
            "unfused stack-local ladder should still contain loads"
        );
    }

    #[test]
    fn select_bitreverse_keeps_ladder_when_intermediate_escapes() {
        let sig = Signature {
            params: vec![Type::I32],
            returns: vec![Type::I32],
        };
        let mut isel =
            InstructionSelector::new_darwin_test("bitrev_escape".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        let (mut instrs, first_combined) = bitreverse_ladder(Type::I32, Value(0), Value(1));
        instrs.push(Instruction {
            opcode: Opcode::Iadd,
            args: vec![first_combined, Value(0)],
            results: vec![Value(2)],
        });
        isel.select_block(entry, &instrs).unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        assert!(
            !insts.iter().any(|inst| inst.opcode == AArch64Opcode::Rbit),
            "must not fuse when a ladder intermediate has an external use"
        );
        assert!(
            insts
                .iter()
                .any(|inst| matches!(inst.opcode, AArch64Opcode::LsrRI | AArch64Opcode::LsrRR)),
            "unfused ladder should still contain shifts"
        );
    }

    #[test]
    fn full_negate_function() {
        // fn negate(i32) -> i32 { return -arg; }
        let sig = Signature {
            params: vec![Type::I32],
            returns: vec![Type::I32],
        };
        let mut isel = InstructionSelector::new_darwin_test("negate".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        // Value(1) = Ineg(Value(0))
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Ineg,
                args: vec![Value(0)],
                results: vec![Value(1)],
            },
            entry,
        )
        .unwrap();

        // Return Value(1)
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Return,
                args: vec![Value(1)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        // COPY (arg) + Neg + Copy (to W0) + RET
        assert_eq!(mblock.insts.len(), 4);
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::Copy);
        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::Neg);
        assert_eq!(mblock.insts[2].opcode, AArch64Opcode::Copy);
        assert_eq!(mblock.insts[2].operands[0], ISelOperand::PReg(gpr::W0));
        assert_eq!(mblock.insts[3].opcode, AArch64Opcode::Ret);
    }

    #[test]
    fn full_fneg_function() {
        // fn fneg(f64) -> f64 { return -arg; }
        let sig = Signature {
            params: vec![Type::F64],
            returns: vec![Type::F64],
        };
        let mut isel = InstructionSelector::new_darwin_test("fneg_fn".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Fneg,
                args: vec![Value(0)],
                results: vec![Value(1)],
            },
            entry,
        )
        .unwrap();

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Return,
                args: vec![Value(1)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        // COPY (arg) + FNEGDr + MOV (to V0) + RET
        assert_eq!(mblock.insts.len(), 4);
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::Copy);
        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::FnegRR);
        assert_eq!(mblock.insts[3].opcode, AArch64Opcode::Ret);
    }

