    #[test]
    fn select_bitcast_i32_to_f32() {
        let sig = Signature {
            params: vec![Type::I32],
            returns: vec![Type::F32],
        };
        let mut isel = InstructionSelector::new_darwin_test("bc_i2f".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Bitcast { to_ty: Type::F32 },
                args: vec![Value(0)],
                results: vec![Value(1)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        // GPR -> FPR: FMOV Sd, Wn
        assert_eq!(
            mfunc.blocks[&entry].insts[1].opcode,
            AArch64Opcode::FmovGprFpr
        );
    }

    #[test]
    fn select_bitcast_i16_to_f16_uses_fmov_gpr_fpr() {
        let (mut isel, entry) = make_empty_isel();
        let src = Value(0);
        let result = Value(1);
        let src_vreg = isel.new_vreg(RegClass::Gpr32);
        isel.define_value(src, ISelOperand::VReg(src_vreg), Type::I16);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Bitcast { to_ty: Type::F16 },
                args: vec![src],
                results: vec![result],
            },
            entry,
        )
        .unwrap();

        match isel.value_map.get(&result) {
            Some(ISelOperand::VReg(vreg)) => assert_eq!(vreg.class, RegClass::Fpr16),
            other => panic!("expected VReg result for bitcast i16->f16, got {:?}", other),
        }
        assert_eq!(isel.value_types.get(&result), Some(&Type::F16));

        let mfunc = isel.finalize();
        assert_eq!(
            mfunc.blocks[&entry].insts[0].opcode,
            AArch64Opcode::FmovGprFpr
        );
    }

