    /// The dynamic-bound guard must put a REGISTER in the carrier's bound slot,
    /// not an immediate. This is the shape `v[k]` with a runtime `v.len()`
    /// produces, which the constant-bound variant cannot express at all.
    ///
    /// The bound slot is what `expand_trap_bounds_check_exact` dispatches on:
    /// a register yields `CmpRR`, an immediate `CmpRI`. Emitting a register and
    /// having it read as an immediate would encode the register NUMBER as the
    /// compare operand — an out-of-bounds access in a program that still looks
    /// bounds-checked.
    #[test]
    fn select_guard_bounds_check_dyn_emits_register_bound() {
        let (mut isel, entry) = make_i64_3arg_isel();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::GuardBoundsCheckDyn { obligation: None },
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        let guard = mblock
            .insts
            .iter()
            .find(|i| i.opcode == AArch64Opcode::TrapBoundsCheckExact)
            .expect("dynamic guard must emit the exact-trap carrier");

        assert_eq!(guard.operands.len(), 3);
        assert_eq!(
            guard.operands[2],
            ISelOperand::VReg(VReg::new(2, RegClass::Gpr64)),
            "bound slot must hold the runtime length REGISTER, not an immediate"
        );
        assert!(
            !matches!(guard.operands[2], ISelOperand::Imm(_)),
            "an Imm here would be read as a compare immediate — silent OOB"
        );
    }

