    #[test]
    fn select_fconst_f64_zero() {
        let (mut isel, entry) = make_empty_isel();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Fconst {
                    ty: Type::F64,
                    imm: 0.0,
                },
                args: vec![],
                results: vec![Value(0)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        // 0.0 is NOT FMOV-immediate-encodable (the immediate form cannot encode
        // zero), so it is materialized via MOVZ #0 + FMOV GPR->FPR rather than
        // FmovImm (which would silently encode +2.0).
        let insts = &mfunc.blocks[&entry].insts;
        assert_eq!(insts[0].opcode, AArch64Opcode::Movz);
        assert_eq!(insts.last().unwrap().opcode, AArch64Opcode::FmovGprFpr);
    }

    // -- Combined FP operations (chaining) --

    #[test]
    fn fp_chain_fabs_then_fsqrt() {
        let sig = Signature {
            params: vec![Type::F64],
            returns: vec![Type::F64],
        };
        let mut isel = InstructionSelector::new_darwin_test("abs_sqrt".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        // result = sqrt(|x|)
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Fabs,
                args: vec![Value(0)],
                results: vec![Value(1)],
            },
            entry,
        )
        .unwrap();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Fsqrt,
                args: vec![Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::FabsRR);
        assert_eq!(mblock.insts[2].opcode, AArch64Opcode::FsqrtRR);
    }

    #[test]
    fn fp_chain_fmul_then_fabs() {
        let (mut isel, entry) = make_f64_isel();

        // result = |x * y|
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Fmul,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Fabs,
                args: vec![Value(2)],
                results: vec![Value(3)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        assert_eq!(mblock.insts[2].opcode, AArch64Opcode::FmulRR);
        assert_eq!(mblock.insts[3].opcode, AArch64Opcode::FabsRR);
    }

