    #[test]
    fn select_atomic_rmw_acquire_emits_a_suffixed_opcodes() {
        // Was `..._acquire_or_emits_ldsetal`: an Acquire RMW used to take the
        // strictly-stronger `AL` (acquire+release) form for every op without a
        // dedicated `A` opcode. All nine ops now have their exact
        // load-acquire-only (`A`, A=1 R=0) LSE opcode, so Acquire selects the
        // EXACT requested ordering — never the AL over-strengthening and never
        // a relaxed downgrade. (The darwin thread Parker's
        // `state.swap(EMPTY, Acquire)` is the Xchg row.)
        for (op, expected_a, forbidden_al) in [
            (
                AtomicRmwOp::Add,
                AArch64Opcode::Ldadda,
                AArch64Opcode::Ldaddal,
            ),
            (
                AtomicRmwOp::Sub,
                AArch64Opcode::Ldadda,
                AArch64Opcode::Ldaddal,
            ),
            (
                AtomicRmwOp::And,
                AArch64Opcode::Ldclra,
                AArch64Opcode::Ldclral,
            ),
            (
                AtomicRmwOp::Or,
                AArch64Opcode::Ldseta,
                AArch64Opcode::Ldsetal,
            ),
            (
                AtomicRmwOp::Xor,
                AArch64Opcode::Ldeora,
                AArch64Opcode::Ldeoral,
            ),
            (
                AtomicRmwOp::Max,
                AArch64Opcode::Ldsmaxa,
                AArch64Opcode::Ldsmaxal,
            ),
            (
                AtomicRmwOp::Min,
                AArch64Opcode::Ldsmina,
                AArch64Opcode::Ldsminal,
            ),
            (
                AtomicRmwOp::UMax,
                AArch64Opcode::Ldumaxa,
                AArch64Opcode::Ldumaxal,
            ),
            (
                AtomicRmwOp::UMin,
                AArch64Opcode::Ldumina,
                AArch64Opcode::Lduminal,
            ),
            (AtomicRmwOp::Xchg, AArch64Opcode::Swpa, AArch64Opcode::Swpal),
        ] {
            for ty in [Type::I32, Type::I64] {
                let (mut isel, entry) = make_empty_isel();
                let val_vreg = isel.new_vreg(reg_class_for_type(&ty));
                isel.define_value(Value(0), ISelOperand::VReg(val_vreg), ty.clone());
                let addr_vreg = isel.new_vreg(RegClass::Gpr64);
                isel.define_value(Value(1), ISelOperand::VReg(addr_vreg), Type::I64);

                isel.select_instruction(
                    &Instruction {
                        opcode: Opcode::AtomicRmw {
                            op,
                            ty: ty.clone(),
                            ordering: AtomicOrdering::Acquire,
                        },
                        args: vec![Value(0), Value(1)],
                        results: vec![Value(2)],
                    },
                    entry,
                )
                .unwrap_or_else(|e| {
                    panic!("Acquire {op:?} on {ty:?} must select an A-suffixed LSE opcode, not fail: {e:?}")
                });

                let mfunc = isel.finalize();
                // The LSE atomic is always the LAST emitted instruction: Sub
                // prepends NEG and And prepends ORN/MVN; the rest emit it alone.
                let last = mfunc.blocks[&entry].insts.last().unwrap();
                assert_eq!(
                    last.opcode, expected_a,
                    "Acquire {op:?} on {ty:?} must emit acquire-only {expected_a:?}"
                );
                assert_ne!(
                    last.opcode, forbidden_al,
                    "Acquire {op:?} must NOT emit the AcqRel {forbidden_al:?} (over-strengthened ordering)"
                );
            }
        }
    }

    #[test]
    fn select_atomic_rmw_release_add_emits_ldaddl() {
        // Was `..._fails_until_release_lse_or_llsc_is_proven`: standalone-Release
        // RMW is now supported via the store-release-only (`L`) LSE opcodes, so
        // Release Add emits LDADDL (A=0, R=1) — not a codegen error, and not the
        // over-strengthened acqrel LDADDAL.
        let (mut isel, entry) = make_empty_isel();
        let val_vreg = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(val_vreg), Type::I64);
        let addr_vreg = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(1), ISelOperand::VReg(addr_vreg), Type::I64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::AtomicRmw {
                    op: AtomicRmwOp::Add,
                    ty: Type::I64,
                    ordering: AtomicOrdering::Release,
                },
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        assert_eq!(
            mfunc.blocks[&entry].insts[0].opcode,
            AArch64Opcode::Ldaddl,
            "AtomicRmw Add with Release should emit release-only LDADDL"
        );
    }

    #[test]
    fn select_cmpxchg_bool_and_integer_widths_preserve_all_ordering_pairs() {
        use AtomicOrdering::{AcqRel, Acquire, Relaxed, Release, SeqCst};
        for (ty, size) in [
            (Type::B1, Some(0)),
            (Type::I8, Some(0)),
            (Type::I16, Some(1)),
            (Type::I32, None),
            (Type::I64, None),
        ] {
            for success in [Relaxed, Acquire, Release, AcqRel, SeqCst] {
                for failure in [Relaxed, Acquire, Release, AcqRel, SeqCst] {
                    let (mut isel, entry) = make_empty_isel();
                    for id in [0, 1] {
                        let reg = isel.new_vreg(reg_class_for_type(&ty));
                        isel.define_value(Value(id), ISelOperand::VReg(reg), ty.clone());
                    }
                    let ptr = isel.new_vreg(RegClass::Gpr64);
                    isel.define_value(Value(2), ISelOperand::VReg(ptr), Type::I64);
                    let result = isel.select_instruction(
                        &Instruction {
                            opcode: Opcode::CmpXchg {
                                ty: ty.clone(),
                                success,
                                failure,
                            },
                            args: vec![Value(0), Value(1), Value(2)],
                            results: vec![Value(3)],
                        },
                        entry,
                    );
                    if matches!(failure, Release | AcqRel) {
                        assert!(
                            matches!(
                                result,
                                Err(ISelError::UnsupportedCmpXchg {
                                    reason: "invalid compare-exchange failure ordering",
                                    ..
                                })
                            ),
                            "{ty:?} {success:?}/{failure:?}: {result:?}"
                        );
                        assert!(isel.finalize().blocks[&entry].insts.is_empty());
                        continue;
                    }
                    result.unwrap();
                    let expected = if failure == SeqCst
                        || matches!(success, AcqRel | SeqCst)
                        || (success == Release && failure == Acquire)
                    {
                        AArch64Opcode::Casal
                    } else if success == Acquire || failure == Acquire {
                        AArch64Opcode::Casa
                    } else if success == Release {
                        AArch64Opcode::Casl
                    } else {
                        AArch64Opcode::Cas
                    };
                    let selected = isel.finalize();
                    let insts = &selected.blocks[&entry].insts;
                    assert_eq!(insts.len(), 2);
                    assert_eq!(insts[0].opcode, AArch64Opcode::MovR);
                    assert_eq!(insts[1].opcode, expected, "{ty:?} {success:?}/{failure:?}");
                    assert_eq!(insts[1].operands.len(), if size.is_some() { 4 } else { 3 });
                    if let Some(size) = size {
                        assert_eq!(insts[1].operands[3], ISelOperand::Imm(size), "{ty:?}");
                    }
                }
            }
        }
    }

    #[test]
    fn select_bool_atomic_load_store_are_bytes_and_rmw_is_logical_only() {
        for (store, ordering) in [
            (false, AtomicOrdering::Relaxed),
            (false, AtomicOrdering::Acquire),
            (false, AtomicOrdering::SeqCst),
            (true, AtomicOrdering::Relaxed),
            (true, AtomicOrdering::Release),
            (true, AtomicOrdering::SeqCst),
        ] {
            let (mut isel, entry) = make_empty_isel();
            isel.set_lse_enabled(false); // Byte load/store needs no LSE admission.
            let ptr = isel.new_vreg(RegClass::Gpr64);
            isel.define_value(Value(0), ISelOperand::VReg(ptr), Type::I64);
            let value = isel.new_vreg(RegClass::Gpr64);
            isel.define_value(Value(1), ISelOperand::VReg(value), Type::B1);
            let instruction = if store {
                Instruction {
                    opcode: Opcode::AtomicStore {
                        ty: Type::B1,
                        ordering,
                    },
                    args: vec![Value(1), Value(0)],
                    results: vec![],
                }
            } else {
                Instruction {
                    opcode: Opcode::AtomicLoad {
                        ty: Type::B1,
                        ordering,
                    },
                    args: vec![Value(0)],
                    results: vec![Value(2)],
                }
            };
            isel.select_instruction(&instruction, entry).unwrap();
            let selected = isel.finalize();
            let insts = &selected.blocks[&entry].insts;
            let opcodes: Vec<AArch64Opcode> = insts.iter().map(|inst| inst.opcode).collect();
            // One byte access; a loaded bool is then `byte != 0` (TST, CSET),
            // register operations only.
            assert_eq!(
                opcodes,
                if store {
                    vec![AArch64Opcode::Stlrb]
                } else {
                    vec![
                        AArch64Opcode::Ldarb,
                        AArch64Opcode::Tst,
                        AArch64Opcode::CSet,
                    ]
                }
            );
        }
        // Bool RMW admits exactly the logical ops (byte-sized); see
        // bool_rmw_admits_only_logical_ops_on_both_profiles.
        for op in [
            AtomicRmwOp::Xchg,
            AtomicRmwOp::And,
            AtomicRmwOp::Or,
            AtomicRmwOp::Xor,
        ] {
            InstructionSelector::require_aarch64_atomic_rmw_lse_coverage(
                op,
                &Type::B1,
                AtomicOrdering::SeqCst,
            )
            .unwrap();
        }
        for op in [
            AtomicRmwOp::Add,
            AtomicRmwOp::Sub,
            AtomicRmwOp::Max,
            AtomicRmwOp::UMin,
        ] {
            assert!(matches!(
                InstructionSelector::require_aarch64_atomic_rmw_lse_coverage(
                    op,
                    &Type::B1,
                    AtomicOrdering::SeqCst
                ),
                Err(ISelError::UnsupportedAtomicRmw { .. })
            ));
        }
    }

    #[test]
    fn select_cmpxchg_seqcst_emits_mov_then_casal() {
        let (mut isel, entry) = make_empty_isel();
        let exp_vreg = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(exp_vreg), Type::I64);
        let des_vreg = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(1), ISelOperand::VReg(des_vreg), Type::I64);
        let addr_vreg = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(2), ISelOperand::VReg(addr_vreg), Type::I64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::CmpXchg {
                    ty: Type::I64,
                    success: AtomicOrdering::SeqCst,
                    failure: AtomicOrdering::SeqCst,
                },
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![Value(3)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        // CmpXchg emits MOV (copy expected) then CASAL
        assert_eq!(
            insts[0].opcode,
            AArch64Opcode::MovR,
            "CmpXchg should first copy expected value with MOV"
        );
        assert_eq!(
            insts[1].opcode,
            AArch64Opcode::Casal,
            "CmpXchg with SeqCst should emit CASAL"
        );
    }

