    // =======================================================================
    // PIECE 1: small constant-length memcpy inlining (exact lanes, no libcall)
    // =======================================================================

    /// Select a `memcpy(dest, src, len)` with a compile-time-constant length and
    /// return the emitted `(opcode, operands)` sequence. `dest`/`src` are I64
    /// pointer vregs; `len` is seeded into `iconst_origins`.
    fn run_const_memcpy(len: i64) -> Vec<(AArch64Opcode, Vec<ISelOperand>)> {
        let (mut isel, entry) = make_empty_isel();
        let d = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(d), Type::I64);
        let s = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(1), ISelOperand::VReg(s), Type::I64);
        isel.iconst_origins.insert(Value(2), (Type::I64, len));
        isel.value_types.insert(Value(2), Type::I64);
        isel.current_block = Some(entry);
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Memcpy,
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        mfunc.blocks[&entry]
            .insts
            .iter()
            .map(|i| (i.opcode, i.operands.clone()))
            .collect()
    }

    fn imm_last(operands: &[ISelOperand]) -> i64 {
        match operands.last() {
            Some(ISelOperand::Imm(v)) => *v,
            other => panic!("expected trailing Imm operand, got {other:?}"),
        }
    }

    /// Byte width of a load lane, or `None` for a non-load opcode. `LdrRI`'s
    /// width follows the destination register class (X=8, W=4).
    fn load_lane_width(opc: AArch64Opcode, operands: &[ISelOperand]) -> Option<u64> {
        match opc {
            AArch64Opcode::LdpRI => Some(16),
            AArch64Opcode::LdrRI => match operands.first() {
                Some(ISelOperand::VReg(v)) if v.class == RegClass::Gpr64 => Some(8),
                Some(ISelOperand::VReg(v)) if v.class == RegClass::Gpr32 => Some(4),
                _ => None,
            },
            AArch64Opcode::LdrhRI => Some(2),
            AArch64Opcode::LdrbRI => Some(1),
            _ => None,
        }
    }

    fn store_lane_width(opc: AArch64Opcode, operands: &[ISelOperand]) -> Option<u64> {
        match opc {
            AArch64Opcode::StpRI => Some(16),
            AArch64Opcode::StrRI => match operands.first() {
                Some(ISelOperand::VReg(v)) if v.class == RegClass::Gpr64 => Some(8),
                Some(ISelOperand::VReg(v)) if v.class == RegClass::Gpr32 => Some(4),
                _ => None,
            },
            AArch64Opcode::StrhRI => Some(2),
            AArch64Opcode::StrbRI => Some(1),
            _ => None,
        }
    }

    #[test]
    fn memcpy_const_len_0_emits_nothing() {
        let insts = run_const_memcpy(0);
        assert!(insts.is_empty(), "len 0 memcpy is a no-op, got {insts:?}");
    }

    #[test]
    fn memcpy_const_len_16_is_single_ldp_stp() {
        let insts = run_const_memcpy(16);
        let opcs: Vec<_> = insts.iter().map(|(o, _)| *o).collect();
        assert_eq!(
            opcs,
            vec![AArch64Opcode::LdpRI, AArch64Opcode::StpRI],
            "16-byte copy is exactly one LDP/STP pair"
        );
    }

    #[test]
    fn memcpy_const_len_32_is_two_ldp_stp_chunks() {
        let insts = run_const_memcpy(32);
        let opcs: Vec<_> = insts.iter().map(|(o, _)| *o).collect();
        assert_eq!(
            opcs,
            vec![
                AArch64Opcode::LdpRI,
                AArch64Opcode::StpRI,
                AArch64Opcode::LdpRI,
                AArch64Opcode::StpRI,
            ]
        );
        // Second chunk is at byte offset 16.
        assert_eq!(imm_last(&insts[2].1), 16);
        assert_eq!(imm_last(&insts[3].1), 16);
    }

    #[test]
    fn memcpy_const_len_13_lanes_8_4_1() {
        // 13 = 8 + 4 + 1 at offsets 0, 8, 12 — EXACT, no over-read.
        let insts = run_const_memcpy(13);
        let opcs: Vec<_> = insts.iter().map(|(o, _)| *o).collect();
        assert_eq!(
            opcs,
            vec![
                AArch64Opcode::LdrRI, // x @0
                AArch64Opcode::StrRI,
                AArch64Opcode::LdrRI, // w @8
                AArch64Opcode::StrRI,
                AArch64Opcode::LdrbRI, // b @12
                AArch64Opcode::StrbRI,
            ]
        );
        assert_eq!(load_lane_width(insts[0].0, &insts[0].1), Some(8));
        assert_eq!(load_lane_width(insts[2].0, &insts[2].1), Some(4));
        assert_eq!(imm_last(&insts[4].1), 12);
    }

    #[test]
    fn memcpy_const_len_31_lanes_16_8_4_2_1() {
        // 31 = 16 + 8 + 4 + 2 + 1 at offsets 0, 16, 24, 28, 30.
        let insts = run_const_memcpy(31);
        let opcs: Vec<_> = insts.iter().map(|(o, _)| *o).collect();
        assert_eq!(
            opcs,
            vec![
                AArch64Opcode::LdpRI, // 16 @0
                AArch64Opcode::StpRI,
                AArch64Opcode::LdrRI, // x @16
                AArch64Opcode::StrRI,
                AArch64Opcode::LdrRI, // w @24
                AArch64Opcode::StrRI,
                AArch64Opcode::LdrhRI, // h @28
                AArch64Opcode::StrhRI,
                AArch64Opcode::LdrbRI, // b @30
                AArch64Opcode::StrbRI,
            ]
        );
    }

    /// EXHAUSTIVE exact-lane coverage: for every inlined length 1..=32, the load
    /// lanes tile `[0, len)` with no gap, no overlap, and no byte read past
    /// `len` (the property that makes an end-of-allocation copy safe), the store
    /// lanes mirror them exactly, and no libc `Bl` is emitted.
    #[test]
    fn memcpy_const_lens_exact_lane_coverage() {
        for len in 1..=INLINE_MEMCPY_MAX_BYTES {
            let insts = run_const_memcpy(len);
            assert!(
                !insts.iter().any(|(o, _)| *o == AArch64Opcode::Bl),
                "len {len}: inlined copy must not call memcpy"
            );
            let n = len as usize;
            let mut loaded = vec![false; n];
            let mut stored = vec![false; n];
            for (opc, ops) in &insts {
                if let Some(w) = load_lane_width(*opc, ops) {
                    let off = imm_last(ops) as usize;
                    let end = off + w as usize;
                    assert!(end <= n, "len {len}: load reads byte {end} past end");
                    for (relative, was_loaded) in loaded[off..end].iter_mut().enumerate() {
                        let b = off + relative;
                        assert!(!*was_loaded, "len {len}: byte {b} loaded twice");
                        *was_loaded = true;
                    }
                } else if let Some(w) = store_lane_width(*opc, ops) {
                    let off = imm_last(ops) as usize;
                    let end = off + w as usize;
                    assert!(end <= n, "len {len}: store writes byte {end} past end");
                    for (relative, was_stored) in stored[off..end].iter_mut().enumerate() {
                        let b = off + relative;
                        assert!(!*was_stored, "len {len}: byte {b} stored twice");
                        *was_stored = true;
                    }
                }
            }
            assert!(
                loaded.iter().all(|&c| c),
                "len {len}: source not fully read"
            );
            assert!(
                stored.iter().all(|&c| c),
                "len {len}: dest not fully written"
            );
        }
    }

    #[test]
    fn memcpy_const_len_33_keeps_libcall() {
        // 33 > INLINE_MEMCPY_MAX_BYTES: the boundary just above the inline cap.
        let insts = run_const_memcpy(INLINE_MEMCPY_MAX_BYTES + 1);
        assert!(
            insts.iter().any(|(o, _)| *o == AArch64Opcode::Bl),
            "len 33 must fall back to the libc memcpy call"
        );
    }

    #[test]
    fn memcpy_nonconst_len_keeps_libcall() {
        // A length NOT in `iconst_origins` is a runtime value: keep the libcall.
        let (mut isel, entry) = make_empty_isel();
        let d = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(d), Type::I64);
        let s = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(1), ISelOperand::VReg(s), Type::I64);
        let n = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(2), ISelOperand::VReg(n), Type::I64);
        isel.current_block = Some(entry);
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Memcpy,
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        assert!(
            mfunc.blocks[&entry]
                .insts
                .iter()
                .any(|i| i.opcode == AArch64Opcode::Bl),
            "non-constant length must call memcpy"
        );
    }

    #[test]
    fn memmove_const_len_keeps_libcall() {
        // memmove has overlap semantics: never inlined, even for a small const.
        let (mut isel, entry) = make_empty_isel();
        let d = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(d), Type::I64);
        let s = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(1), ISelOperand::VReg(s), Type::I64);
        isel.iconst_origins.insert(Value(2), (Type::I64, 16));
        isel.current_block = Some(entry);
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Memmove,
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        let bl = mfunc.blocks[&entry]
            .insts
            .iter()
            .find(|i| i.opcode == AArch64Opcode::Bl);
        assert_eq!(
            bl.expect("memmove keeps its BL").operands[0],
            ISelOperand::Symbol("memmove".to_string()),
        );
    }

    // =======================================================================
    // PIECE 1b: small constant-length ZERO memset inlining (STP/STR of XZR)
    // =======================================================================

    /// Select a `memset(dest, fill, len)` where `fill` and `len` are seeded
    /// compile-time constants and return the emitted `(opcode, operands)`
    /// sequence. `dest` is an I64 pointer vreg.
    fn run_const_memset(fill: i64, len: i64) -> Vec<(AArch64Opcode, Vec<ISelOperand>)> {
        let (mut isel, entry) = make_empty_isel();
        let d = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(d), Type::I64);
        isel.iconst_origins.insert(Value(1), (Type::I32, fill));
        isel.value_types.insert(Value(1), Type::I32);
        isel.iconst_origins.insert(Value(2), (Type::I64, len));
        isel.value_types.insert(Value(2), Type::I64);
        isel.current_block = Some(entry);
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Memset,
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        mfunc.blocks[&entry]
            .insts
            .iter()
            .map(|i| (i.opcode, i.operands.clone()))
            .collect()
    }

    /// Byte width of a zero-register store lane, or `None` for anything else.
    /// `StrRI`'s width follows the zero register's class (XZR=8, WZR=4).
    fn zero_store_lane_width(opc: AArch64Opcode, operands: &[ISelOperand]) -> Option<u64> {
        match opc {
            AArch64Opcode::StpRI => Some(16),
            AArch64Opcode::StrRI => match operands.first() {
                Some(ISelOperand::PReg(p)) if *p == XZR => Some(8),
                Some(ISelOperand::PReg(p)) if *p == WZR => Some(4),
                _ => None,
            },
            AArch64Opcode::StrhRI => Some(2),
            AArch64Opcode::StrbRI => Some(1),
            _ => None,
        }
    }

    #[test]
    fn memset_const_zero_len_0_emits_nothing() {
        let insts = run_const_memset(0, 0);
        assert!(insts.is_empty(), "len 0 memset is a no-op, got {insts:?}");
    }

    #[test]
    fn memset_const_zero_len_16_is_single_stp_xzr() {
        // The CreateNode shape: llvm.memset(ptr, 0, 16) = one stp xzr, xzr.
        let insts = run_const_memset(0, 16);
        assert_eq!(insts.len(), 1, "16-byte zeroing is exactly one STP");
        let (opc, ops) = &insts[0];
        assert_eq!(*opc, AArch64Opcode::StpRI);
        assert_eq!(ops[0], ISelOperand::PReg(XZR));
        assert_eq!(ops[1], ISelOperand::PReg(XZR));
        assert_eq!(imm_last(ops), 0);
    }

    /// EXHAUSTIVE exact-lane coverage: for every inlined length 1..=32, the
    /// zero-register store lanes tile `[0, len)` with no gap, no overlap, and
    /// no byte written past `len` (the property that makes an
    /// end-of-allocation fill safe), and no libc `Bl` is emitted.
    #[test]
    fn memset_const_zero_lens_exact_lane_coverage() {
        for len in 1..=INLINE_MEMCPY_MAX_BYTES {
            let insts = run_const_memset(0, len);
            assert!(
                !insts.iter().any(|(o, _)| *o == AArch64Opcode::Bl),
                "len {len}: inlined zeroing must not call memset"
            );
            let n = len as usize;
            let mut stored = vec![false; n];
            for (opc, ops) in &insts {
                let w = zero_store_lane_width(*opc, ops)
                    .unwrap_or_else(|| panic!("len {len}: unexpected inst {opc:?} {ops:?}"));
                let off = imm_last(ops) as usize;
                let end = off + w as usize;
                assert!(end <= n, "len {len}: store writes byte {end} past end");
                for (relative, was_stored) in stored[off..end].iter_mut().enumerate() {
                    let b = off + relative;
                    assert!(!*was_stored, "len {len}: byte {b} stored twice");
                    *was_stored = true;
                }
            }
            assert!(
                stored.iter().all(|&c| c),
                "len {len}: dest not fully zeroed"
            );
        }
    }

    #[test]
    fn memset_const_zero_len_33_keeps_libcall() {
        // 33 > INLINE_MEMCPY_MAX_BYTES: the boundary just above the inline cap.
        let insts = run_const_memset(0, INLINE_MEMCPY_MAX_BYTES + 1);
        assert!(
            insts.iter().any(|(o, _)| *o == AArch64Opcode::Bl),
            "len 33 must fall back to the libc memset call"
        );
    }

    #[test]
    fn memset_nonzero_fill_keeps_libcall() {
        // A non-zero fill needs a materialized byte-splat: keep the libcall.
        let insts = run_const_memset(1, 16);
        assert!(
            insts.iter().any(|(o, _)| *o == AArch64Opcode::Bl),
            "non-zero fill must call memset"
        );
    }

    #[test]
    fn memset_nonconst_fill_keeps_libcall() {
        // A fill value NOT in `iconst_origins` is a runtime value — even if it
        // happens to be zero dynamically, the libcall is the only sound choice.
        let (mut isel, entry) = make_empty_isel();
        let d = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(d), Type::I64);
        let f = isel.new_vreg(RegClass::Gpr32);
        isel.define_value(Value(1), ISelOperand::VReg(f), Type::I32);
        isel.iconst_origins.insert(Value(2), (Type::I64, 16));
        isel.value_types.insert(Value(2), Type::I64);
        isel.current_block = Some(entry);
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Memset,
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        assert!(
            mfunc.blocks[&entry]
                .insts
                .iter()
                .any(|i| i.opcode == AArch64Opcode::Bl),
            "non-constant fill must call memset"
        );
    }

    #[test]
    fn memset_nonconst_len_keeps_libcall() {
        // A length NOT in `iconst_origins` is a runtime value: keep the libcall.
        let (mut isel, entry) = make_empty_isel();
        let d = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(d), Type::I64);
        isel.iconst_origins.insert(Value(1), (Type::I32, 0));
        isel.value_types.insert(Value(1), Type::I32);
        let n = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(2), ISelOperand::VReg(n), Type::I64);
        isel.current_block = Some(entry);
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Memset,
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        assert!(
            mfunc.blocks[&entry]
                .insts
                .iter()
                .any(|i| i.opcode == AArch64Opcode::Bl),
            "non-constant length must call memset"
        );
    }

    // =======================================================================
    // PIECE 2: constant GEP/Iadd offset -> ADD-immediate addressing
    // =======================================================================

    /// `emit_pointer_add_const` must produce an ENCODABLE sequence for every
    /// non-negative offset. `add_imm12_form_boundaries` above covers the pure
    /// decision function; this covers what is actually emitted, which is where
    /// the bug was — `select_struct_gep` bypassed the decision entirely and
    /// emitted a bare `AddRI` with whatever offset it had. That is legal ISel
    /// and only fails in the ENCODER, so a unit test at this level is what
    /// would have caught it.
    #[test]
    fn pointer_add_const_is_encodable_at_every_magnitude() {
        use AArch64Opcode::{AddRI, AddRIShift12, AddRR, MovR, Movk, Movz};

        fn emit(off: i64) -> Vec<(AArch64Opcode, Vec<ISelOperand>)> {
            let (mut isel, entry) = make_empty_isel();
            let base = isel.new_vreg(RegClass::Gpr64);
            let dst = isel.new_vreg(RegClass::Gpr64);
            isel.current_block = Some(entry);
            isel.emit_pointer_add_const(entry, dst, ISelOperand::VReg(base), off);
            let mfunc = isel.finalize();
            mfunc.blocks[&entry]
                .insts
                .iter()
                .map(|i| (i.opcode, i.operands.clone()))
                .collect()
        }
        // Any immediate operand actually emitted must fit the 12-bit field.
        fn imms_in_range(insts: &[(AArch64Opcode, Vec<ISelOperand>)]) -> bool {
            insts.iter().all(|(op, ops)| {
                !matches!(op, AddRI | AddRIShift12)
                    || ops.iter().all(|o| match o {
                        ISelOperand::Imm(v) => (0..=0xFFF).contains(v),
                        _ => true,
                    })
            })
        }

        // 0 -> a plain move, no arithmetic at all.
        let zero = emit(0);
        assert_eq!(zero.len(), 1);
        assert_eq!(zero[0].0, MovR);

        // Inside imm12 -> one ADD.
        for off in [1i64, 8, 0xFFF] {
            let insts = emit(off);
            assert_eq!(insts.len(), 1, "off={off:#x}: {insts:?}");
            assert_eq!(insts[0].0, AddRI);
            assert!(imms_in_range(&insts), "off={off:#x}: {insts:?}");
        }

        // Low bits clear -> the LSL #12 form. 0x1000 is the exact offset that
        // used to fail: element 512 of an `[i64; 576]`.
        for off in [0x1000i64, 0x2000, 0xFFF000] {
            let insts = emit(off);
            assert_eq!(insts.len(), 1, "off={off:#x}: {insts:?}");
            assert_eq!(insts[0].0, AddRIShift12);
            assert!(imms_in_range(&insts), "off={off:#x}: {insts:?}");
        }

        // Both halves set -> two adds, shifted then low. 0x11F8 is element 575
        // of an `[i64; 576]` (4600 bytes), the shape-coverage repro.
        for off in [0x1001i64, 4600, 0xFFFFFF] {
            let insts = emit(off);
            assert_eq!(insts.len(), 2, "off={off:#x}: {insts:?}");
            assert_eq!(insts[0].0, AddRIShift12);
            assert_eq!(insts[1].0, AddRI);
            assert!(imms_in_range(&insts), "off={off:#x}: {insts:?}");
        }

        // Past 24 bits -> materialize and add REGISTERS; no truncated immediate.
        for off in [0x100_0000i64, 0x1234_5678] {
            let insts = emit(off);
            assert!(
                insts.iter().any(|(o, _)| *o == AddRR),
                "off={off:#x} must use the register add path: {insts:?}"
            );
            assert!(
                insts.iter().any(|(o, _)| matches!(o, Movz | Movk)),
                "off={off:#x} must materialize the offset: {insts:?}"
            );
            assert!(
                !insts.iter().any(|(o, _)| matches!(o, AddRI | AddRIShift12)),
                "off={off:#x} must not emit a truncated ADD-immediate: {insts:?}"
            );
        }
    }

    #[test]
    fn add_imm12_form_boundaries() {
        use AArch64Opcode::{AddRI, AddRIShift12};
        assert_eq!(aarch64_add_imm12_form(0), Some((AddRI, 0)));
        assert_eq!(aarch64_add_imm12_form(1), Some((AddRI, 1)));
        assert_eq!(aarch64_add_imm12_form(0xFFF), Some((AddRI, 0xFFF)));
        // Just above imm12: only encodable as an LSL#12 form because low bits clear.
        assert_eq!(aarch64_add_imm12_form(0x1000), Some((AddRIShift12, 1)));
        assert_eq!(aarch64_add_imm12_form(0x2000), Some((AddRIShift12, 2)));
        assert_eq!(
            aarch64_add_imm12_form(0xFFF000),
            Some((AddRIShift12, 0xFFF))
        );
        // Both halves set -> needs two adds -> not a single-instruction form.
        assert_eq!(aarch64_add_imm12_form(0x1001), None);
        // Beyond 0xFFF<<12.
        assert_eq!(aarch64_add_imm12_form(0x1000000), None);
        // Negative displacement is not ADD-immediate encodable.
        assert_eq!(aarch64_add_imm12_form(-1), None);
        // A 0xFADE global-address stub magnitude (never a plain Iconst at ISel,
        // but the guard rejects it regardless of how it might arrive).
        assert_eq!(
            aarch64_add_imm12_form(0xFADE_0000_0000_0004_u64 as i64),
            None
        );
    }

    /// Select `Iadd(a0, a1)` where one operand is a seeded constant; return the
    /// emitted opcode sequence.
    fn run_iadd_with_const(
        const_on_rhs: bool,
        const_val: i64,
        ty: Type,
    ) -> Vec<(AArch64Opcode, Vec<ISelOperand>)> {
        let (mut isel, entry) = make_empty_isel();
        let reg = isel.new_vreg(reg_class_for_type(&ty));
        let (reg_v, const_v) = if const_on_rhs {
            (Value(0), Value(1))
        } else {
            (Value(1), Value(0))
        };
        isel.define_value(reg_v, ISelOperand::VReg(reg), ty.clone());
        isel.value_types.insert(reg_v, ty.clone());
        isel.iconst_origins.insert(const_v, (ty.clone(), const_val));
        isel.value_types.insert(const_v, ty.clone());
        isel.current_block = Some(entry);
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Iadd,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        mfunc.blocks[&entry]
            .insts
            .iter()
            .map(|i| (i.opcode, i.operands.clone()))
            .collect()
    }

    #[test]
    fn iadd_const_rhs_folds_to_addri() {
        let insts = run_iadd_with_const(true, 20, Type::I64);
        assert_eq!(insts.len(), 1, "one folded ADD, no MOVZ: {insts:?}");
        assert_eq!(insts[0].0, AArch64Opcode::AddRI);
        assert_eq!(imm_last(&insts[0].1), 20);
    }

    #[test]
    fn iadd_const_lhs_folds_commutatively() {
        let insts = run_iadd_with_const(false, 12, Type::I64);
        assert_eq!(insts.len(), 1, "const on LHS still folds: {insts:?}");
        assert_eq!(insts[0].0, AArch64Opcode::AddRI);
        assert_eq!(imm_last(&insts[0].1), 12);
    }

    #[test]
    fn iadd_const_shift12_folds() {
        let insts = run_iadd_with_const(true, 0x2000, Type::I64);
        assert_eq!(insts.len(), 1);
        assert_eq!(insts[0].0, AArch64Opcode::AddRIShift12);
        assert_eq!(imm_last(&insts[0].1), 2);
    }

    #[test]
    fn iadd_i32_const_folds_to_addri() {
        let insts = run_iadd_with_const(true, 7, Type::I32);
        assert_eq!(insts.len(), 1);
        assert_eq!(insts[0].0, AArch64Opcode::AddRI);
        assert_eq!(imm_last(&insts[0].1), 7);
    }

    #[test]
    fn iadd_nonencodable_const_falls_back_to_register_add() {
        // 0x1001 is not a single ADD-immediate: keep the materialize + AddRR.
        let insts = run_iadd_with_const(true, 0x1001, Type::I64);
        assert!(
            insts.iter().any(|(o, _)| *o == AArch64Opcode::AddRR),
            "non-encodable constant must use the register add path: {insts:?}"
        );
        assert!(
            !insts
                .iter()
                .any(|(o, _)| matches!(o, AArch64Opcode::AddRI | AArch64Opcode::AddRIShift12)),
            "must not emit a truncated ADD-immediate: {insts:?}"
        );
    }

    #[test]
    fn iadd_small_negative_const_folds_to_subri() {
        // `x + (-3)` == `x - 3`: a small negative constant folds to a single
        // SUB (immediate), not a materialize + AddRR. This is the loop
        // decrement `i--` (`add i, -1`) that otherwise squats a register on the
        // constant. Fires for RHS or LHS constant (addition commutes).
        for on_rhs in [true, false] {
            let insts = run_iadd_with_const(on_rhs, -3, Type::I64);
            assert_eq!(insts.len(), 1, "one folded SUB, no MOVZ: {insts:?}");
            assert_eq!(insts[0].0, AArch64Opcode::SubRI);
            assert_eq!(imm_last(&insts[0].1), 3, "negated to +3");
        }
        // The canonical decrement `i - 1`.
        let dec = run_iadd_with_const(true, -1, Type::I64);
        assert_eq!(dec[0].0, AArch64Opcode::SubRI);
        assert_eq!(imm_last(&dec[0].1), 1);
        // 32-bit decrement folds too (SubRI on the W register).
        let dec32 = run_iadd_with_const(true, -1, Type::I32);
        assert_eq!(dec32[0].0, AArch64Opcode::SubRI);
        assert_eq!(imm_last(&dec32[0].1), 1);
    }

    #[test]
    fn iadd_min_negative_imm12_folds_to_subri() {
        // -0xFFF is the largest-magnitude single SUB-immediate.
        let insts = run_iadd_with_const(true, -0xFFF, Type::I64);
        assert_eq!(insts.len(), 1);
        assert_eq!(insts[0].0, AArch64Opcode::SubRI);
        assert_eq!(imm_last(&insts[0].1), 0xFFF);
    }

    #[test]
    fn iadd_large_negative_const_falls_back_to_register_add() {
        // -0x1001 exceeds the imm12 SUB range and there is no SubRIShift12, so
        // it keeps the materialize + AddRR path (no truncated/wrong immediate).
        let insts = run_iadd_with_const(true, -0x1001, Type::I64);
        assert!(
            insts.iter().any(|(o, _)| *o == AArch64Opcode::AddRR),
            "out-of-range negative constant must use the register add path: {insts:?}"
        );
        assert!(
            !insts.iter().any(|(o, _)| *o == AArch64Opcode::SubRI),
            "must not emit a truncated SUB-immediate: {insts:?}"
        );
    }

    /// Select `Isub(a0, a1)` where one operand is a seeded constant; return
    /// the emitted opcode sequence. `lhs_ty` and `rhs_ty` are separate so the
    /// mixed-width operand preparation can be tested directly.
    fn run_isub_with_const(
        const_on_rhs: bool,
        const_val: i64,
        lhs_ty: Type,
        rhs_ty: Type,
    ) -> Vec<(AArch64Opcode, Vec<ISelOperand>)> {
        let (mut isel, entry) = make_empty_isel();
        let (reg_v, reg_ty, const_v, const_ty) = if const_on_rhs {
            (Value(0), lhs_ty, Value(1), rhs_ty)
        } else {
            (Value(1), rhs_ty, Value(0), lhs_ty)
        };
        let reg = isel.new_vreg(reg_class_for_type(&reg_ty));
        isel.define_value(reg_v, ISelOperand::VReg(reg), reg_ty.clone());
        isel.value_types.insert(reg_v, reg_ty);
        isel.iconst_origins
            .insert(const_v, (const_ty.clone(), const_val));
        isel.value_types.insert(const_v, const_ty);
        isel.current_block = Some(entry);
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Isub,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        mfunc.blocks[&entry]
            .insts
            .iter()
            .map(|i| (i.opcode, i.operands.clone()))
            .collect()
    }

    #[test]
    fn isub_nonnegative_rhs_const_folds_to_subri() {
        for (ty, imm) in [
            (Type::I64, 0),
            (Type::I64, 1),
            (Type::I64, 0xFFF),
            (Type::I32, 7),
        ] {
            let insts = run_isub_with_const(true, imm, ty.clone(), ty);
            assert_eq!(
                insts.len(),
                1,
                "one folded SUB, no constant materialization: {insts:?}"
            );
            assert_eq!(insts[0].0, AArch64Opcode::SubRI);
            assert_eq!(imm_last(&insts[0].1), imm);
        }
    }

    #[test]
    fn isub_const_lhs_does_not_fold_noncommutatively() {
        let insts = run_isub_with_const(false, 7, Type::I64, Type::I64);
        assert!(
            insts.iter().any(|(opc, _)| *opc == AArch64Opcode::SubRR),
            "const - x must preserve operand order on the register path: {insts:?}"
        );
        assert!(
            !insts.iter().any(|(opc, _)| *opc == AArch64Opcode::SubRI),
            "const - x must not be rewritten as x - const: {insts:?}"
        );
    }

    #[test]
    fn isub_unencodable_rhs_const_falls_back_to_register_sub() {
        for imm in [-1, 0x1000] {
            let insts = run_isub_with_const(true, imm, Type::I64, Type::I64);
            assert!(
                insts.iter().any(|(opc, _)| *opc == AArch64Opcode::SubRR),
                "unencodable RHS constant must use register SUB: imm={imm}, {insts:?}"
            );
            assert!(
                !insts.iter().any(|(opc, _)| *opc == AArch64Opcode::SubRI),
                "unencodable RHS constant must not be truncated: imm={imm}, {insts:?}"
            );
        }
    }

    #[test]
    fn isub_mixed_i32_lhs_i64_const_widens_before_subri() {
        let insts = run_isub_with_const(true, 7, Type::I32, Type::I64);
        assert_eq!(insts.len(), 2, "expected UXTW then folded SUB: {insts:?}");
        assert_eq!(insts[0].0, AArch64Opcode::Uxtw);
        assert_eq!(insts[1].0, AArch64Opcode::SubRI);
        assert_eq!(imm_last(&insts[1].1), 7);
        let ISelOperand::VReg(wide_lhs) = insts[1].1[1] else {
            panic!("folded SUB lhs must be the widened vreg: {:?}", insts[1]);
        };
        assert_eq!(wide_lhs.class, RegClass::Gpr64);
        assert_eq!(insts[0].1[0], ISelOperand::VReg(wide_lhs));
    }

    /// Select an `ArrayGep(elem_ty)` with a seeded constant index; return the
    /// emitted opcode sequence. (The ArrayGep path is still reached for
    /// multi-index / ExtractElement GEPs.)
    fn run_array_gep_const_index(
        elem_ty: Type,
        index: i64,
    ) -> Vec<(AArch64Opcode, Vec<ISelOperand>)> {
        let (mut isel, entry) = make_empty_isel();
        let base = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(base), Type::I64);
        isel.iconst_origins.insert(Value(1), (Type::I64, index));
        isel.value_types.insert(Value(1), Type::I64);
        isel.current_block = Some(entry);
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::ArrayGep { elem_ty },
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        mfunc.blocks[&entry]
            .insts
            .iter()
            .map(|i| (i.opcode, i.operands.clone()))
            .collect()
    }

    #[test]
    fn array_gep_const_index_elem1_folds_to_addri() {
        let insts = run_array_gep_const_index(Type::I8, 12);
        assert_eq!(insts.len(), 1);
        assert_eq!(insts[0].0, AArch64Opcode::AddRI);
        assert_eq!(imm_last(&insts[0].1), 12);
    }

    #[test]
    fn array_gep_const_index_scaled_folds_to_addri() {
        // i32 elements: index 5 -> byte offset 20.
        let insts = run_array_gep_const_index(Type::I32, 5);
        assert_eq!(insts.len(), 1);
        assert_eq!(insts[0].0, AArch64Opcode::AddRI);
        assert_eq!(imm_last(&insts[0].1), 20);
    }

    #[test]
    fn array_gep_const_index_zero_is_pointer_copy() {
        let insts = run_array_gep_const_index(Type::I32, 0);
        assert_eq!(insts.len(), 1);
        assert_eq!(insts[0].0, AArch64Opcode::MovR);
    }

    #[test]
    fn array_gep_const_index_nonencodable_falls_back() {
        // i32 elements, index 0x800 -> byte offset 0x2000 (encodable via LSL#12).
        let enc = run_array_gep_const_index(Type::I32, 0x800);
        assert_eq!(enc[0].0, AArch64Opcode::AddRIShift12);
        // i32 elements, index 0x401 -> 0x1004 -> both halves set -> NOT foldable;
        // drops to the shift-then-add path (LslRI + AddRR).
        let insts = run_array_gep_const_index(Type::I32, 0x401);
        assert!(
            insts.iter().any(|(o, _)| *o == AArch64Opcode::AddRR),
            "non-encodable scaled offset uses the register path: {insts:?}"
        );
        assert!(!insts.iter().any(|(o, _)| *o == AArch64Opcode::AddRI));
    }

    #[test]
    fn array_gep_runtime_index_unchanged() {
        // A non-constant index keeps the existing AddRR (elem 1) form.
        let (mut isel, entry) = make_empty_isel();
        let base = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(base), Type::I64);
        let idx = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(1), ISelOperand::VReg(idx), Type::I64);
        isel.current_block = Some(entry);
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::ArrayGep { elem_ty: Type::I8 },
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        assert_eq!(mfunc.blocks[&entry].insts[0].opcode, AArch64Opcode::AddRR);
    }

    #[test]
    fn select_memset_no_results() {
        // memset produces no results (void return)
        let (mut isel, entry) = make_empty_isel();

        let v0 = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(v0), Type::I64);
        let v1 = isel.new_vreg(RegClass::Gpr32);
        isel.define_value(Value(1), ISelOperand::VReg(v1), Type::I32);
        let v2 = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(2), ISelOperand::VReg(v2), Type::I64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Memset,
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![], // void
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        // After BL, there should be no result copy (no return value)
        let bl_idx = mblock
            .insts
            .iter()
            .position(|i| i.opcode == AArch64Opcode::Bl)
            .unwrap();
        // No Copy/MovR after the BL (no return value to copy)
        let post_bl_copy = mblock.insts[bl_idx + 1..]
            .iter()
            .any(|i| i.opcode == AArch64Opcode::MovR || i.opcode == AArch64Opcode::Copy);
        assert!(!post_bl_copy, "memset is void — no result copy after BL");
    }

