    #[test]
    fn select_i128_iconst_zero() {
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel = InstructionSelector::new_darwin_test("const128".to_string(), sig);
        let entry = Block(0);
        isel.func.ensure_block(entry);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I128,
                    imm: 0,
                },
                args: vec![],
                results: vec![Value(0)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        // Two MOVZ instructions (lo=0, hi=0)
        assert_eq!(mblock.insts.len(), 2);
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::Movz);
        assert_eq!(mblock.insts[0].operands[1], ISelOperand::Imm(0));
        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::Movz);
        assert_eq!(mblock.insts[1].operands[1], ISelOperand::Imm(0));
    }

    #[test]
    fn select_i128_iconst_small_positive() {
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel = InstructionSelector::new_darwin_test("const128".to_string(), sig);
        let entry = Block(0);
        isel.func.ensure_block(entry);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I128,
                    imm: 42,
                },
                args: vec![],
                results: vec![Value(0)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        // MOVZ lo(42) + MOVZ hi(0) = 2 instructions
        assert_eq!(mblock.insts.len(), 2);
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::Movz);
        assert_eq!(mblock.insts[0].operands[1], ISelOperand::Imm(42));
        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::Movz);
        assert_eq!(mblock.insts[1].operands[1], ISelOperand::Imm(0)); // hi = 0
    }

    #[test]
    fn select_i128_iconst_negative() {
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel = InstructionSelector::new_darwin_test("const128".to_string(), sig);
        let entry = Block(0);
        isel.func.ensure_block(entry);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I128,
                    imm: -1,
                },
                args: vec![],
                results: vec![Value(0)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        // lo = 0xFFFF_FFFF_FFFF_FFFF: MOVZ + 3 MOVK = 4
        // hi = 0xFFFF_FFFF_FFFF_FFFF: MOVZ + 3 MOVK = 4
        // Total: 8 instructions
        assert_eq!(mblock.insts.len(), 8);
        // lo half: MOVZ 0xFFFF, MOVK 0xFFFF<<16, MOVK 0xFFFF<<32, MOVK 0xFFFF<<48
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::Movz);
        assert_eq!(mblock.insts[0].operands[1], ISelOperand::Imm(0xFFFF));
        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::Movk);
        assert_eq!(mblock.insts[2].opcode, AArch64Opcode::Movk);
        assert_eq!(mblock.insts[3].opcode, AArch64Opcode::Movk);
        // hi half: same pattern
        assert_eq!(mblock.insts[4].opcode, AArch64Opcode::Movz);
        assert_eq!(mblock.insts[4].operands[1], ISelOperand::Imm(0xFFFF));
        assert_eq!(mblock.insts[5].opcode, AArch64Opcode::Movk);
        assert_eq!(mblock.insts[6].opcode, AArch64Opcode::Movk);
        assert_eq!(mblock.insts[7].opcode, AArch64Opcode::Movk);
    }

    #[test]
    fn select_i128_iconst_large() {
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel = InstructionSelector::new_darwin_test("const128".to_string(), sig);
        let entry = Block(0);
        isel.func.ensure_block(entry);

        // 0x1_0000 (65536) — needs MOVZ + 1 MOVK for lo, MOVZ for hi
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I128,
                    imm: 0x1_0000,
                },
                args: vec![],
                results: vec![Value(0)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        // lo = 0x10000: MOVZ 0 + MOVK 1<<16 = 2 instructions
        // hi = 0: MOVZ 0 = 1 instruction
        // Total: 3
        assert_eq!(mblock.insts.len(), 3);
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::Movz); // lo: MOVZ #0
        assert_eq!(mblock.insts[0].operands[1], ISelOperand::Imm(0));
        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::Movk); // lo: MOVK #1, LSL#16
        assert_eq!(mblock.insts[1].operands[1], ISelOperand::Imm(1));
        assert_eq!(mblock.insts[1].operands[2], ISelOperand::Imm(16));
        assert_eq!(mblock.insts[2].opcode, AArch64Opcode::Movz); // hi: MOVZ #0
    }

    // =======================================================================
    // i128 shift tests
    // =======================================================================

    /// Helper: create isel with one i128 value and one scalar shift amount.
    fn make_i128_shift_isel() -> (InstructionSelector, Block) {
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel = InstructionSelector::new_darwin_test("i128shift".to_string(), sig);
        let entry = Block(0);
        isel.func.ensure_block(entry);

        // i128 value as (lo, hi) pair
        let v0_lo = isel.new_vreg(RegClass::Gpr64);
        let v0_hi = isel.new_vreg(RegClass::Gpr64);
        isel.define_i128_value(Value(0), v0_lo, v0_hi);

        // scalar shift amount
        let v1 = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(1), ISelOperand::VReg(v1), Type::I64);

        (isel, entry)
    }

    /// Like `make_i128_shift_isel` but the shift amount `Value(1)` is a
    /// compile-time constant tracked in the `Iconst` pre-scan (as the bridge
    /// emits it for a constant amount), so the constant-fold guard fires.
    fn make_i128_const_shift_isel(amt: i64) -> (InstructionSelector, Block) {
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel = InstructionSelector::new_darwin_test("i128cshift".to_string(), sig);
        let entry = Block(0);
        isel.func.ensure_block(entry);

        let v0_lo = isel.new_vreg(RegClass::Gpr64);
        let v0_hi = isel.new_vreg(RegClass::Gpr64);
        isel.define_i128_value(Value(0), v0_lo, v0_hi);

        // Constant shift amount, as `seed_iconst_origins` would record it.
        isel.iconst_origins.insert(Value(1), (Type::I64, amt));

        (isel, entry)
    }

    fn run_i128_const_shift(op: Opcode, amt: i64) -> Vec<AArch64Opcode> {
        let (mut isel, entry) = make_i128_const_shift_isel(amt);
        isel.select_instruction(
            &Instruction {
                opcode: op,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        mfunc.blocks[&entry]
            .insts
            .iter()
            .map(|i| i.opcode)
            .collect()
    }

    #[test]
    fn i128_const_shl_folds_are_csel_free() {
        use AArch64Opcode::{LslRI, LsrRI, MovR, Movz, OrrRR};
        // amt == 0: identity (two MovR).
        assert_eq!(run_i128_const_shift(Opcode::Ishl, 0), vec![MovR, MovR]);
        // 0 < amt < 64: lo<<amt, lo>>(64-amt), hi<<amt, OR.
        assert_eq!(
            run_i128_const_shift(Opcode::Ishl, 5),
            vec![LslRI, LsrRI, LslRI, OrrRR]
        );
        // amt == 64: lo' = 0, hi' = lo.
        assert_eq!(run_i128_const_shift(Opcode::Ishl, 64), vec![Movz, MovR]);
        // 64 < amt < 128: lo' = 0, hi' = lo << (amt-64).
        assert_eq!(run_i128_const_shift(Opcode::Ishl, 72), vec![Movz, LslRI]);
        // Every fold is csel-free.
        for amt in [0, 1, 5, 63, 64, 65, 72, 127] {
            let ops = run_i128_const_shift(Opcode::Ishl, amt);
            assert!(!ops.contains(&AArch64Opcode::Csel), "amt={amt} has csel");
        }
    }

    #[test]
    fn i128_const_lshr_folds_are_csel_free() {
        use AArch64Opcode::{LslRI, LsrRI, MovR, Movz, OrrRR};
        assert_eq!(run_i128_const_shift(Opcode::Ushr, 0), vec![MovR, MovR]);
        // 0 < amt < 64: lo>>amt, hi<<(64-amt), OR, hi>>amt (logical).
        assert_eq!(
            run_i128_const_shift(Opcode::Ushr, 5),
            vec![LsrRI, LslRI, OrrRR, LsrRI]
        );
        // amt == 64: lo' = hi, hi' = 0.
        assert_eq!(run_i128_const_shift(Opcode::Ushr, 64), vec![MovR, Movz]);
        // 64 < amt < 128: lo' = hi >> (amt-64), hi' = 0.
        assert_eq!(run_i128_const_shift(Opcode::Ushr, 72), vec![LsrRI, Movz]);
        for amt in [0, 1, 5, 63, 64, 65, 72, 127] {
            let ops = run_i128_const_shift(Opcode::Ushr, amt);
            assert!(!ops.contains(&AArch64Opcode::Csel), "amt={amt} has csel");
        }
    }

    #[test]
    fn i128_const_ashr_folds_use_arith_signfill_and_no_csel() {
        use AArch64Opcode::{AsrRI, LslRI, LsrRI, MovR, OrrRR};
        assert_eq!(run_i128_const_shift(Opcode::Sshr, 0), vec![MovR, MovR]);
        // 0 < amt < 64: lo>>amt (LOGICAL), hi<<(64-amt), OR, hi>>a amt (ASR).
        assert_eq!(
            run_i128_const_shift(Opcode::Sshr, 5),
            vec![LsrRI, LslRI, OrrRR, AsrRI]
        );
        // amt == 64: lo' = hi, hi' = sign (ASR #63).
        assert_eq!(run_i128_const_shift(Opcode::Sshr, 64), vec![MovR, AsrRI]);
        // 64 < amt < 128: lo' = hi >>a (amt-64), hi' = sign (ASR #63).
        assert_eq!(run_i128_const_shift(Opcode::Sshr, 72), vec![AsrRI, AsrRI]);
        for amt in [0, 1, 5, 63, 64, 65, 72, 127] {
            let ops = run_i128_const_shift(Opcode::Sshr, amt);
            assert!(!ops.contains(&AArch64Opcode::Csel), "amt={amt} has csel");
        }
    }

    #[test]
    fn i128_const_shift_amount_masks_mod_128() {
        // rustc masks the amount by width-1; the fold reduces `& 127`. 200 -> 72,
        // so an over-width constant selects the same fold as amt 72 (hi>>a(8),
        // sign-fill), never the general funnel.
        assert_eq!(
            run_i128_const_shift(Opcode::Sshr, 200),
            run_i128_const_shift(Opcode::Sshr, 72)
        );
        // 128 -> 0 == identity.
        assert_eq!(
            run_i128_const_shift(Opcode::Ishl, 128),
            vec![AArch64Opcode::MovR, AArch64Opcode::MovR]
        );
    }

    #[test]
    fn i128_variable_shift_keeps_general_funnel() {
        // A non-constant amount (VReg, absent from the Iconst pre-scan) must NOT
        // fold — it keeps the general funnel+csel path (the runtime control).
        let (mut isel, entry) = make_i128_shift_isel();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Ushr,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        let ops: Vec<_> = mfunc.blocks[&entry]
            .insts
            .iter()
            .map(|i| i.opcode)
            .collect();
        assert!(
            ops.contains(&AArch64Opcode::Csel),
            "variable-amount i128 shift must keep the general funnel (csel)"
        );
    }

    #[test]
    fn select_i128_shl_emits_correct_sequence() {
        let (mut isel, entry) = make_i128_shift_isel();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Ishl,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        // Includes an explicit shift==0 spill guard because AArch64 LSRV masks
        // register shift amounts modulo 64.
        assert_eq!(mblock.insts.len(), 14);
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::Movz); // c64
        assert_eq!(mblock.insts[0].operands[1], ISelOperand::Imm(64));
        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::Movz); // zero
        assert_eq!(mblock.insts[1].operands[1], ISelOperand::Imm(0));
        assert_eq!(mblock.insts[2].opcode, AArch64Opcode::SubRR); // neg_shift
        assert_eq!(mblock.insts[3].opcode, AArch64Opcode::LsrRR); // raw lo_spill
        assert_eq!(mblock.insts[4].opcode, AArch64Opcode::CmpRI); // cmp shift, 0
        assert_eq!(mblock.insts[5].opcode, AArch64Opcode::Csel); // guarded lo_spill
        assert_eq!(
            mblock.insts[5].operands[3],
            ISelOperand::CondCode(AArch64CC::EQ)
        );
        assert_eq!(mblock.insts[6].opcode, AArch64Opcode::LslRR); // hi_shifted
        assert_eq!(mblock.insts[7].opcode, AArch64Opcode::OrrRR); // hi_normal
        assert_eq!(mblock.insts[8].opcode, AArch64Opcode::LslRR); // lo_normal
        assert_eq!(mblock.insts[9].opcode, AArch64Opcode::SubRR); // big_shift
        assert_eq!(mblock.insts[10].opcode, AArch64Opcode::LslRR); // hi_big
        assert_eq!(mblock.insts[11].opcode, AArch64Opcode::CmpRI); // cmp shift, 64
        assert_eq!(mblock.insts[12].opcode, AArch64Opcode::Csel); // dst_lo
        assert_eq!(
            mblock.insts[12].operands[3],
            ISelOperand::CondCode(AArch64CC::HS)
        );
        assert_eq!(mblock.insts[13].opcode, AArch64Opcode::Csel); // dst_hi
        assert_eq!(
            mblock.insts[13].operands[3],
            ISelOperand::CondCode(AArch64CC::HS)
        );
    }

