    #[test]
    fn select_i128_ashr_emits_correct_sequence() {
        let (mut isel, entry) = make_i128_shift_isel();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Sshr,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        // Includes an explicit shift==0 spill guard because AArch64 LSLV masks
        // register shift amounts modulo 64.
        assert_eq!(mblock.insts.len(), 16);
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::Movz); // c64
        assert_eq!(mblock.insts[0].operands[1], ISelOperand::Imm(64));
        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::Movz); // c63
        assert_eq!(mblock.insts[1].operands[1], ISelOperand::Imm(63));
        assert_eq!(mblock.insts[2].opcode, AArch64Opcode::Movz); // zero
        assert_eq!(mblock.insts[3].opcode, AArch64Opcode::SubRR); // neg_shift
        assert_eq!(mblock.insts[4].opcode, AArch64Opcode::LslRR); // raw hi_spill
        assert_eq!(mblock.insts[5].opcode, AArch64Opcode::CmpRI); // cmp shift, 0
        assert_eq!(mblock.insts[6].opcode, AArch64Opcode::Csel); // guarded hi_spill
        assert_eq!(
            mblock.insts[6].operands[3],
            ISelOperand::CondCode(AArch64CC::EQ)
        );
        assert_eq!(mblock.insts[7].opcode, AArch64Opcode::LsrRR); // lo_shifted
        assert_eq!(mblock.insts[8].opcode, AArch64Opcode::OrrRR); // lo_normal
        assert_eq!(mblock.insts[9].opcode, AArch64Opcode::AsrRR); // hi_normal
        assert_eq!(mblock.insts[10].opcode, AArch64Opcode::SubRR); // big_shift
        assert_eq!(mblock.insts[11].opcode, AArch64Opcode::AsrRR); // lo_big
        assert_eq!(mblock.insts[12].opcode, AArch64Opcode::AsrRR); // hi_sign (ASR by 63)
        assert_eq!(mblock.insts[13].opcode, AArch64Opcode::CmpRI); // cmp shift, 64
        assert_eq!(mblock.insts[14].opcode, AArch64Opcode::Csel); // dst_hi
        assert_eq!(
            mblock.insts[14].operands[3],
            ISelOperand::CondCode(AArch64CC::HS)
        );
        assert_eq!(mblock.insts[15].opcode, AArch64Opcode::Csel); // dst_lo
    }

    #[test]
    fn select_i128_ashr_accepts_i128_iconst_shift_amount() {
        let (mut isel, entry) = make_i128_isel();
        let instructions = vec![
            Instruction {
                opcode: Opcode::Imul,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I128,
                    imm: 63,
                },
                args: vec![],
                results: vec![Value(3)],
            },
            Instruction {
                opcode: Opcode::Sshr,
                args: vec![Value(2), Value(3)],
                results: vec![Value(4)],
            },
            Instruction {
                opcode: Opcode::Trunc { to_ty: Type::I64 },
                args: vec![Value(4)],
                results: vec![Value(5)],
            },
        ];

        isel.select_block(entry, &instructions).unwrap();
        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        assert!(
            !mblock
                .insts
                .iter()
                .any(|inst| inst.opcode == AArch64Opcode::Smulh),
            "shift != 64 must not take the SMULH fast path"
        );
        assert!(
            mblock
                .insts
                .iter()
                .any(|inst| inst.opcode == AArch64Opcode::AsrRR),
            "normal i128 arithmetic shift lowering should emit ASR register ops"
        );
    }

